/** 사용 설명서: 기능마다 간단한 그림 + 설명 */
class HelpActivity : Activity() {
    /** v3.9.2: 화면 크기 자동 맞춤 (Ui.fit) */
    override fun attachBaseContext(newBase: android.content.Context) { super.attachBaseContext(Ui.fit(newBase)) }


    private fun dp(v: Int) = Ui.dp(this, v)

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        window.statusBarColor = Ui.BG
        window.navigationBarColor = Ui.BG
        val col = Ui.column(this)
        val top = Ui.row(this)
        top.addView(Ui.button(this, "← 뒤로") { finish() }.apply { minHeight = dp(44) }, LinearLayout.LayoutParams(WRAP, WRAP))
        top.addView(Ui.text(this, 20f, Ui.TEXT, true, "사용 설명서"), LinearLayout.LayoutParams(WRAP, WRAP).apply { leftMargin = dp(14) })
        col.addView(top)

        col.addView(Ui.button(this, "▶ 처음 안내 다시 보기 (그림 6장)", true) { Guide.show(this) }, Ui.lp(this, MATCH, WRAP, top = 14))
        col.addView(Ui.button(this, "📋 업데이트 내역 (종류별)") { History.show(this) }.apply { minHeight = dp(46) }, Ui.lp(this, MATCH, WRAP, top = 8))
        col.addView(Ui.text(this, 12f, Ui.SUB, false, "궁금한 기능을 누르면 펼쳐져요. 다시 누르면 접혀요."),
            Ui.lp(this, MATCH, WRAP, top = 6))

        section(col, HelpPic.REMOTE, "1. 출조 시작 · 카드 눌러 +1",
            "• '출조 시작'을 누르고 배·항구를 적어요 (한 번 적으면 다음부터 목록에서 골라요).\n" +
            "• 주황 카드 = 1번 어종, 파란 카드 = 2번 어종. 카드를 누를 때마다 +1, 시각이 초 단위로 저장돼요.\n" +
            "• 카드 오른쪽 위 연필(✎)을 누르면 어종을 바꿔요. 출조 중에도, 끝난 뒤에도 돼요.\n" +
            "• 화면을 꺼도 기록돼요. 알림창의 +1 버튼으로도 기록할 수 있어요.\n" +
            "• 출조 중엔 버튼이 빨간 '■ 출조 종료'로 바뀌어요.\n" +
            "• 출조 중 카드 아래 '같이 출조 중' 칸: 같이 출조한 그룹원의 마릿수가 실시간으로 나와요 (아래 두 번째 그림 ③). 끝낸 사람은 1시간 동안 '종료했어요'로 보여요.",
            R.drawable.guide_g1_start, R.drawable.guide_g7_live)

        section(col, HelpPic.REMOTE, "2. 리모컨 (1~8번) · 갤럭시 워치",
            "• 🎮 어떤 리모컨을 사야 하나요? (v6.3) 블루투스 음악(미디어) 리모컨만 돼요. 버튼에 VOL+ · VOL− · ⏮ · ⏭ · ⏯ 그림이 있는 리모컨이에요. 화면을 꺼도, 다른 앱을 켜 둬도 기록돼요.\n" +
            "   ✅ 되는 것: 자동차 핸들 · 자전거 핸들용 음악 리모컨, 'Music · Media control' 리모컨\n" +
            "   ❌ 안 되는 것: 틱톡 · 쇼츠 넘기기 리모컨(화면 밀기 방식이라 안 세져요), 셀카 · 카메라 셔터 리모컨(신호가 1개뿐), 마우스 모드 리모컨(화면에 화살표가 생김)\n" +
            "   🛒 살 때 팁: 상품 설명에 'Music', 'Media', '볼륨', '이전 · 다음 곡'이 있는지 확인하세요. '틱톡', '숏폼', '페이지 넘김', '셀카'라고 쓰인 건 피하세요.\n" +
            "   ⚠ 가운데(재생) 버튼을 길게 누르면 음성 비서가 켜지는 리모컨도 있어요. '길게 = 마지막 기록 취소'는 다른 버튼으로 쓰세요.\n" +
            "   🔊 (v6.20) 볼륨 버튼을 누르면 폰 음량만 바뀌던 리모컨도 이제 등록 · 기록돼요. 앱이 음량 바뀜을 알아듣고 음량은 바로 원래대로 되돌려요 (출조 중엔 등록한 볼륨 버튼일 때만). 음량이 최대 · 0이면 한 칸 옮겨 두고 끝나면 되돌려요.\n" +
            "• 메인 '기록 방식 바꾸기' → '리모컨'을 누르면 커튼이 펼쳐지고 1번·2번… 줄이 보여요. '＋ 리모컨 버튼 추가'로 최대 8번까지 늘려요.\n" +
            "• 줄 옆 [리모컨 버튼]을 누르고, 리모컨에서 그 번호로 쓸 버튼을 한 번 누르면 등록돼요 (앱이 미리 정하지 않아요). 다른 번호에 쓰던 버튼이면 이 번호로 옮겨져요.\n" +
            "• ✎로 버튼 이름(예: 위 큰 버튼)을 붙이고, ✕로 지워요.\n" +
            "• 리모컨 N번 = 화면 N번째 카드예요. 1번 주황 · 2번 하늘 카드, 3번부터는 퀵 버튼 순서(카드 이름 앞 ③④…). 어종은 카드의 ✎에서 그때그때 바꾸면 돼요 — 리모컨 설정은 한 번만.\n" +
            "• 진동: 홀수 번호 짧게 1번, 짝수 번호 짧게 2번. 버튼을 길게(약 0.8초) 누르면 마지막 기록 취소.\n" +
            "• 갤럭시 워치: '갤럭시 워치'를 켜고, 출조 중 워치의 음악 화면에서 ⏮ (왼쪽) = 1번, ⏭ (오른쪽) = 2번. 연달아 눌러도 누른 만큼 세요.\n" +
            "• (v6.81) 🤏 두 번 꼬집기 (갤럭시 워치 7 · 울트라 · 8): '갤럭시 워치'를 켜면 아래 [꼬집기: 끔 · 1번 어종 · 고른 어종]. '1번 어종' = 꼬집기마다 1번 +1 (⏮ 1번 · ⏭ 2번 그대로). '고른 어종' = 꼬집기마다 고른 어종 +1 · 워치 ⏮⏭ 는 어종 바꾸기 (진동 횟수 = 번호 · 워치 음악 화면 제목에 ▶). 워치 설정: 설정 → 유용한 기능 → 제스처(두 번 꼬집기) → '미디어 재생/일시정지' (버전마다 이름이 조금 달라요). 블루투스 이어폰 · 차가 연결될 때 '재생' 신호로 한 마리가 세질 수 있으니 그럴 땐 '끔'.\n" +
            "• (v6.56) ⌚ 리모컨으로 셀 때 워치 진동: ⚙ 개인 설정 '⌚ 리모컨으로 셀 때 워치 진동'을 켜면 폰에 '🎣 주꾸미 12마리' 알림이 떠서 워치가 울려요 (1번 = 한 번 · 2번↑ = 두 번 · 취소 = 길게 · 5초 뒤 사라짐). 삼성은 폰 화면이 꺼져 있을 때만 워치로 보내요.\n" +
            "• (v6.61) 🔊 조과 소리: 메인 '＋ 어종 추가' 옆 '🔊 조과 소리' 칸을 누르면 켬/끔. 켜면 리모컨으로 셀 때 폰에서 '띵' (취소는 낮은 '뚱'). 칸을 꾹 누르면 소리(띵 · 뽀롱 · 딸랑 · 퐁당)를 고르고 '번호마다 다르게'(2번 이상 = 두 번)를 켤 수 있어요. 크기는 폰 미디어 음량을 따라가요.\n" +
            "• (v6.61) 🌙 꺼진 화면(AOD)에 마릿수: 리모컨을 등록했거나 워치 기록을 켜면 꺼진 화면 시계 · 잠금화면의 '음악 정보' 자리에 '주꾸미 13 · 갑오징어 4 · 우럭 2'와 '총 19마리 · 2시간 10분째'가 나와요. 폰 설정 → 잠금화면 및 AOD → Always On Display → '음악 정보 표시'를 켜 주세요 (기종마다 이름이 다를 수 있어요). 화면을 켜 두는 것보다 배터리를 훨씬 적게 써요.\n" +
            "• (v6.63) 🔒 잠금화면에 아이콘만 보이고 마릿수가 안 보이면: ⚙ 설정 → [📱 폰 잠금화면 알림 설정 열기] → 폰 설정 잠금화면 및 AOD → 알림 → '상세히'. 안드로이드 16 폰은 [⚡ 실시간 알림(나우바) 허용하기]를 켜면 나우바 · 상태바에 '🎣 주꾸미 13'이 떠요 (폰마다 안 될 수 있어요).")

        section(col, HelpPic.TIDE, "3. 물때 · 날씨 (시간별 / 주간)",
            "• '물때 보기 ›' 또는 물때 한 줄을 누르면: 물높이 그래프, 만조·간조, 일출·일몰 (국립해양조사원 예보). ◀ ▶ 또는 날짜를 눌러 다른 날을 봐요.\n" +
            "• 맨 위에서 관측소를 바꾸거나 검색(예: 무창포)하고, 만조·간조 알람(10~60분 전)을 정해요. 출조 중일 때 소리·진동으로 알려줘요.\n" +
            "• '시간별' 탭: 하늘, 기온, 바람(16방위·풍속 m/s·최대 돌풍), 파도(파향·파고 m·주기 s), 수온이 세로 목록으로 나와요 (기상청 단기예보). 내 위치 칸이 육지면 가까운 바다 칸의 기상청 파고를 써요.\n" +
            "• 날씨 그림: ⚡ 뇌우(낙뢰) · 💨 강풍 10노트↑ · 🌀 돌풍 20노트↑ · 🌧 비 · ☀ 맑음 …\n" +
            "• '주간 (7일)' 탭: 날마다 날씨·최고/최저 기온·바람·파고·물때·물세기 %. 하늘·기온·비·파고는 기상청(오늘~3일 뒤 단기예보, 그 뒤 중기예보)이고, 날짜 아래 초록 '기상청'으로 표시돼요. 파고 아래 작은 숫자는 기상청 해상예보 범위예요.\n" +
            "• 수온: 지난 시간은 근처 관측소의 '실측'(초록으로 강조), 앞으로는 '예상'이에요.\n" +
            "• 물세기: 오늘 조차가 사리 때의 몇 %인지. 그래프 아래 막대는 시간별 물흐름 세기 (높고 주황일수록 물살이 셈).\n" +
            "• (v6.22) 물세기 아래 '↗ 사는 물때'(조금 → 사리, 날마다 물살이 세짐 · 초록) / '↘ 죽는 물때'(사리 → 조금, 날마다 약해짐 · 보라) · 사리 · 조금까지 며칠. 그 아래 앞뒤 7일 물세기 작은 막대 (노란 테두리 = 고른 날).\n" +
            "• '그래프에 보기' 칩으로 cm 눈금·만조·간조·일출·일몰·지금 표시를 켜고 꺼요 (고른 건 저장).\n" +
            "• 물때(몇 물)는 실제 그믐 시각으로 계산해요 (서해 7물때식). 출조를 시작하면 미리 받아 둬서 바다에서 인터넷이 안 돼도 보여요.", R.drawable.guide_g2_tide)

        section(col, HelpPic.GROUP, "4. 그룹 · 공지 · 일정",
            "• 구글 로그인 → 그룹 만들기, 또는 친구가 보낸 초대 코드로 가입.\n" +
            "• 맨 아래 '👥 그룹' 탭을 누르면 큰 창이 열려요. 맨 위에 '지금 ○○ 그룹에서 쓰는 중'이 크게 보여요.\n" +
            "• 큰 창에서: 내 그룹 바꾸기, 출조 종류(선상·해루질·워킹·원투 …) 고르기, 공지, 일정, 그룹 출조 기록, 그룹 관리.\n" +
            "• (v6.37) 버튼의 빨간 'NEW N' = 아직 안 본 새 공지 · 일정 · 출조 기록 · 채팅 (내가 올린 건 빼요). 열어 보면 사라지고, 새 글이 오면 다시 떠요. 아래 '👥 그룹' 탭 빨간 숫자도 같아요.\n" +
            "• (v6.68) ↕ 내 그룹 순서 바꾸기: 초록 그룹 카드를 눌러 '그룹 바꾸기' 창 → 맨 아래 [↕ 순서 바꾸기] → 줄마다 ▲▼ → [✓ 완료]. 줄을 꾹 누르면 위로 · 아래로 · 맨 위로. 나만 보는 순서이고 다른 폰에서도 같아요. 새로 가입한 그룹은 맨 아래로 가요.\n" +
            "• 출조 전날엔 그룹 버튼과 일정 버튼이 초록으로 '내일 출조!'를 알려줘요.\n" +
            "• 일정은 그룹원 누구나 올리고 고치고 지울 수 있어요 (내가 쓴 것). 공지는 그룹장이 써요.\n" +
            "• (v6.39) 일정마다 [🙋 참석] [🤔 미정] [🙅 불참]을 눌러요 (다시 누르면 취소). 현황 줄을 누르면 누가 무슨 답을 했는지 · 한마디 · 아직 답 안 한 사람이 보여요. 일정을 올릴 때 인원 제한을 적으면 다 찬 뒤엔 누른 순서대로 대기예요.\n" +
            "• (v6.44) 참석을 누른 일정은 전날 낮 12시에 '⏰ 내일 출조예요!' 알림이 와요. 일정을 고치면 공지에 올라간 글도 같이 바뀌어요. 그룹장은 👥 멤버 줄 오른쪽 ⋯ 로 멤버를 내보낼 수 있어요.\n" +
            "• (v6.40) 🔔 그룹 알림: 그룹원 출조 중 · 채팅 새 글 · 새 공지 · 새 일정 · 내 일정 참석 답을 상단 알림으로 알려 줘요. 1시간마다 정각쯤 확인해서 조금 늦을 수 있어요. 앱을 보고 있을 땐 안 울리고, ⚙ 설정 '🔔 그룹 알림'에서 하나씩 켜고 끌 수 있어요.\n" +
            "• 그룹 출조 기록: 기간·사람별로 모아 보고, 어종별 합계와 많이 잡은 사람 순위(맨 앞 '🚤 출조 횟수' = 출조 많이 간 사람). 새로 올라온 기록은 강조돼요.\n" +
            "• 💬 댓글: 카드 아래 '💬 댓글 N'을 누르면 출조 상세 아래 댓글 칸이 열려요. 그룹원만 보이고, 내 댓글은 꾹 눌러 고치기 · 지우기. 내 출조나 내가 댓글 단 출조에 새 댓글이 오면 빨간 NEW · 알림으로 알려줘요.\n" +
            "• 그룹장(왕관): 이름·공지 수정, 우리 그룹 출조 종류 추가·빼기, 초대 코드 새로 만들기, 멤버 내보내기, 멤버 출조 내리기, 그룹장 넘겨주기, 그룹 삭제.", R.drawable.guide_g3_group)

        section(col, HelpPic.GROUP, "5. 같이 출조 중 (실시간)",
            "• 같은 그룹 사람이 같이 출조 중이고 가까우면 (기본 1km, ⚙ 개인 설정에서 바꿈), 카드 아래에 그 사람 마릿수가 보여요.\n" +
            "• 잡으면 몇 초 안에 서로 반영돼요. '3분 전'처럼 언제 바뀌었는지도 나와요.\n" +
            "• 출조를 끝낸 사람은 1시간 동안 '○○님은 출조를 종료했어요 · 시각 · 마릿수'로 보여요.\n" +
            "• 지도에도 같이 출조 중인 사람이 이름표와 함께 보여요. 종료한 사람은 흐리게.\n" +
            "• 친구가 어종 칭호를 넘으면 알림 (⚙에서 끌 수 있어요).", R.drawable.guide_g7_live, R.drawable.guide_g6_mates)

        section(col, HelpPic.CAL, "6. 출조 종료 · 기록 보기",
            "• 빨간 '■ 출조 종료'를 누르면 기록 화면이 열려요. 그룹에 자동으로 올라가요 (0마리면 안 올라감, 경로 숨기기 가능).\n" +
            "• 기록 화면에서 이용료(무료/유료·금액)와 준비물을 바로 적고 고쳐요. 같은 배·항구로 다음에 가면 미리 채워져요.\n" +
            "• 시간대별 요약: 몇 시에 몇 마리, 사진 몇 장인지 한눈에. 시간대별 입질 그래프는 어종마다 색이 달라요 (위에 색 설명 · 막대를 누르면 그 시간 어종별 마릿수).\n" +
            "• 금액과 준비물은 내 기록과 그룹에만 보이고, 전체 조황에는 '유료' 여부만 올라가요.", R.drawable.guide_g4_end)

        section(col, HelpPic.CAL, "7. '⋯ 더보기' · 지난 출조",
            "• '⋯ 더보기': 사용 설명서, 지난 출조, 전체 조황·포인트 도감, 지금 그룹, 경로 저장, 버전.\n" +
            "• 지난 출조: 날짜는 연도까지 (예: 2026년 10월 28일) + 옆에 '1년 6개월 전'처럼 작은 표시. 몇 년 전 같은 달이면 노랑.\n" +
            "• 여러 개 지우기: 지난 출조 오른쪽 위 '☑ 선택' → 체크(전체 선택·오늘 것만·이 날짜·10마리 이하) → '선택한 N개 삭제'. 폰·서버 백업·올린 그룹·전체 게시판에서 같이 지워져요.\n" +
            "• 기록은 폰에 저장되고, 로그인하면 서버에도 백업돼서 폰을 바꿔도 복원돼요.\n" +
            "• 카드 오른쪽 위 배지: 하늘 '그룹 (N)' = N개 그룹에 공유, 보라 '전체' = 전체 게시판 공개, 주황 '나만'. '그룹 (N)'을 누르면 공유 그룹을 바꿀 수 있어요.", R.drawable.guide_g5_menu)

        section(col, HelpPic.MAP, "8. 지도",
            "• 왼쪽 위 '지도 (그룹 · 현위치)' 버튼: 이동 경로와 고기 잡은 자리를 점으로. 겹친 점은 숫자로 묶여요.\n" +
            "• 출조 중에는 내 위치가 작은 배 모양 (뱃머리 = 가는 방향). 같이 출조 중인 그룹원도 보여요.\n" +
            "• '지난 기록' 버튼으로 내 예전 포인트와 그룹 친구 포인트를 반투명으로 봐요.\n" +
            "• (v6.37) '🌋 지진 4일' 버튼: 최근 4일 우리나라 주변 지진을 핀으로 (숫자 = 규모). 누르면 시각 · 위치 · 깊이 · 내 위치에서 거리. 지진해일 특보가 있으면 지도 맨 위에 빨간 띠, 출조 중이면 알람이 울려요.\n" +
            "• (v6.43) 지진 핀을 누르면 흐린 원(느끼는 범위) · 진한 원(조심 범위)이 그려지고 내 위치 기준 안내가 나와요 (대략 계산). 출조 중 지도의 ＋ − 아래 조준 버튼: 파랑이면 내 위치를 따라가는 중, 지도를 끌면 꺼지고 누르면 다시 내 배로 가요.\n" +
            "• (v6.68) 📌 포인트 (v6.72 · v6.81 버튼과 상자가 한 덩어리 · 꽂는 중엔 버튼 주황): 지도 왼쪽 [📌 포인트]를 누르면 (v6.91) 지도 아래에서 바가 올라와요 (🔍 장소 · 🗂 지도 표시도 같이 · 손잡이나 같은 버튼을 누르면 내려가요) (v6.79: ＋ 포인트 추가 · 👁 포인트 보기 · 🐟 저장된 어종). [＋ 포인트 추가]를 누르면 지도 가운데에 별 모양 핀이 생겨요. 핀을 손가락으로 끌어 원하는 자리로 옮기고, (v6.73) 원 안에서 두 손가락을 벌리면 반경이 커지고 좁히면 작아져요 (원 밖에서는 지도 확대 · 축소). 핀 위 [💾 저장]을 누르면 저장 창이 떠요 (✕ 취소 · 저장 창을 그냥 닫으면 다시 옮길 수 있어요). 저장 창에서 이름 · 설명 · 반경(50m~5km · v6.91) · 어종(자주 잡은 어종 칩 · '＋ 어종 더'로 전체 목록에서 찾기 · 없으면 직접 추가 · 10개까지) · 누구에게 보일지(🔒 나만 · 👥 그룹 · 🌐 전체 게시판)를 정해요. 색은 내 것 주황 · 그룹 하늘 · 전체 보라. 포인트를 누르면 설명과 그 범위 안 지난 조과 · 물때 · 원 분석. 상자의 👁 포인트 보기 = 보일 포인트(내 것 · 그룹 · 전체) 고르기 · 🐟 저장된 어종 = 포인트에 적은 어종별 개수 · 고른 어종 포인트만 지도에(여러 개) · 목록 누르면 그 자리로. 이미 꽂은 포인트는 [✎ 고치기 · 옮기기 · 공유]로 같은 방법으로 옮겨요. (v6.80) 👥 그룹은 여러 개를 체크해 한 번에 공유할 수 있어요 (지우면 모든 그룹에서 같이 지워져요). 그룹 창 [🗺 그룹 지도]엔 그 그룹 포인트와 그룹 출조 조과 점이 같이 보여요 ([🐟 조과 ▾] = 기간 · 어종 · 항구 보기).\n" +
            "• (v6.74) 지도 그림: 아래 '지도' 탭 · 퀵바 · 위젯의 지도는 지구본 + 보라 'All' 그림이에요 (내 것 · 그룹 · 전체를 다 보는 지도). 그룹 창의 그룹 지도는 하늘 '그룹' 그림이에요.\n" +
            "• (v6.73) 🗺 지도 메뉴는 지도 왼쪽 세로 줄이에요: 🔍 장소 · 📜 지난 기록 · 📌 포인트 · 🗂 지도 표시 · 🌬 바람. '🗂 지도 표시'를 누르면 옆에 묶음이 펼쳐져요 — ⚓ 항구 · 🌋 지진 4일 · 🦀 해루질 참고용 · 🛰 위성 · 👁 포인트 보기 (다시 누르면 접힘). 닫기는 제목 줄 오른쪽. '내 위치로'는 오른쪽 아래 ◎ 버튼을 써요. 세로 줄이 길면 위아래로 밀어요.\n" +
            "• (v6.73) ⚓ 항구: 지도에 전국 항구 · 포구 · 선착장이 자동으로 나와요 (멀리 = 작은 점 · 확대하면 ⚓ + 이름 · 작은 선착장은 더 확대하면). 항구를 누르면 [🌊 물때 · 날씨] [📌 포인트 꽂기] [🧭 길 찾기(카카오맵)] [☆ 즐겨찾기(물때 창 지점)]. '🗂 지도 표시 → ⚓ 항구'로 켜고 끄기 (기억해요). 자료는 오픈스트리트맵 · 카카오 지도라 작은 선착장은 빠졌을 수 있어요.\n" +
            "• (v6.70) 지도 위 버튼 누르기: '📜 지난 기록'은 (v6.71) 메인 지도를 처음 열면 켜져 있고 아래 상자는 접혀 있어요(▸). 누르면 상자가 펼쳐지고 → 한 번 더 누르면 꺼지고 → 다시 누르면 켜짐(접힘). 그다음부터는 마지막으로 둔 상태 그대로 열려요. '☑ 해루질 참고용'은 누를 때마다 켜기 + 상자 펼침 → 상자 접기 → 끄기. 상자의 × 는 바로 끄기. 포인트 지도 '그룹 포인트'도 같아요 (끈 뒤 다시 켜면 예전에 고른 그룹 그대로).\n" +
            "• (v6.60) 📜 지난 기록을 켜면 버튼 아래 상자 하나에 출조 색 · 어종 · 합계가 묶여 나와요 (× 로 닫기). 처음엔 '내 기록 + 전체 게시판 · 전체 기간'. [보기 바꾸기 ▾]에서 누구 기록 · 연도(전체 연도면 해마다 같은 달끼리) · 몇 월~몇 월을 고를 수 있어요. 게시판 글은 최근 글부터 정해진 개수만 받아서 아주 오래된 글은 빠질 수 있어요.\n" +
            "• (v6.58) 🐟 지난 기록 어종 골라 보기: 지난 기록을 켜면 위에 '🐟 어종' 줄이 나와요. 처음엔 전체 · 어종 칩을 누르면 그 어종만 진하게(여러 개 가능) · '⋯ 고르기'에서 체크로 고르고 안 고른 어종을 흐리게/숨기기. 고른 건 기억해요.\n" +
            "• (v6.38) 메인 지도는 열자마자 🌋 지진 · 지난 기록이 켜져 있어요 (버튼을 누르면 꺼져요). 지난 기록은 폰에 저장해 둔 걸 바로 보여 주고, 새로 올라온 글만 받아요.\n" +
            "• 이동 거리(km·해리), 출발지에서의 직선거리, 포인트까지 '북동쪽 320m'처럼 방향·거리.\n" +
            "• '내 위치로'를 누르면 내 위치로 지도가 옮겨가요.")

        section(col, HelpPic.PHOTO, "9. 사진 올리기",
            "• 출조 기록 화면에서 '사진 추가'로 여러 장을 한 번에 골라요.\n" +
            "• 찍은 시각에 가장 가까운 조과 옆에 작은 사진이 자동으로 붙어요.\n" +
            "• 그룹에 올리면 친구들도 보고, 누르면 크게 확대돼요.")
        tip(col, "꿀팁: 잘 먹히는 에기(색·무게)가 있으면 그 시간대에 에기 사진을 한 장 찍어 두세요. " +
            "나중에 사진을 올리면 그 시간 조과 옆에 에기 사진이 붙어서 \"몇 시에 어떤 에기로 잘 나왔는지\" 한눈에 보여요.")

        section(col, HelpPic.MAP, "10. 전체 조황 · 포인트 도감",
            "• 출조를 끝낼 때 '전체 게시판에도 공개'를 체크하면 모든 사람이 보는 게시판에 올라가요 (기본은 꺼짐).\n" +
            "• 올라가는 건 날짜·종류·어종별 마릿수·시각·물때·위치. 이동 경로와 배 이름은 안 올라가요.\n" +
            "• 위치는 '정확한 위치' 또는 '대략적으로만'(반경 약 500m 원) 중에 골라요. 사진은 고를 때만, 이름은 닉네임이나 익명.\n" +
            "• '포인트 도감': 어종을 고르면 잘 나온 자리 순위(1시간당 마릿수)와 잘 나온 물때·시간대·월.\n" +
            "• 같은 어종도 출조 종류가 다르면 따로 집계돼요. 예: 쭈꾸미 (선상낚시), 쭈꾸미 (해루질).\n" +
            "• 장난 기록은 눌러서 '이 사람 차단'. 여러 사람이 차단하면 '⚠ 신고 N'이 보이고, 기준 이상이면 모든 집계에서 빠져요.\n" +
            "• 공개는 출조 기록 화면에서 언제든 내릴 수 있어요.")

        section(col, HelpPic.FISH, "11. ⚙ 개인 설정 · 닉네임 · 돌파 칭호",
            "• 오른쪽 맨 위 ⚙ (또는 맨 아래 '⋯ 더보기' → ⚙ 설정): 닉네임, 꺼진 화면·잠금 화면 표시, 친구 돌파 알림, 같이 출조 거리.\n" +
            "• 닉네임은 언제든 바로 바꿀 수 있어요 (다른 사람과 같은 이름은 안 돼요). 다른 사람에겐 구글 실명 대신 닉네임이 보여요.\n" +
            "• (v6.43) 🚫 '관리자 · 운영자 · 운영진 · 관리팀 · admin · 운영'이 들어간 이름은 닉네임 · 채팅 이름 · 그룹 이름표 · 포인트에 쓸 수 없어요 (띄어쓰기 · 특수문자를 섞어도 막혀요). 이미 그런 이름이면 앱을 켤 때 바꾸라고 안내해요.\n" +
            "• 어종마다 1마리(첫 손맛)·10(손맛 봤다)·30(오늘 좀 되네)·50(물 만났다)·70(줄 터졌다)·100(백마리 클럽)·120(장인)·150(명인)·200(전설)·250(살아있는 전설)·300(바다의 신)마리를 넘으면 칭호·테두리·색종이·진동으로 축하해 줘요. 지난 출조엔 🏅 도장이 남아요.\n" +
            "• (v6.18) 맨 아래 '📄 개인정보처리방침 보기' · '📄 동의 내용 다시 보기'.\n" +
            "• (v6.18) '🚪 계정 삭제 (회원 탈퇴)': 구글 로그인으로 한 번 더 확인하면 서버의 내 기록(그룹 · 게시판 · 채팅 · 백업 · 닉네임)과 계정이 지워져요. 폰 안 기록은 남아요. 내가 그룹장인 그룹이 있으면 먼저 그룹장을 넘기거나 그룹을 지워야 해요.")

        section(col, HelpPic.TIDE, "12. 일출·일몰 · 입질 시간 메모",
            "• 물때 칸과 그래프에 일출·일몰이 보여요. 해 뜨기 전·해 진 뒤는 어둡게 칠해져요.\n" +
            "• 출조 기록 화면의 '입질 시간 메모': 어종마다 30분 안에 가장 많이 잡힌 때를 '일출 후 40분 ~ 1시간 10분'처럼.\n" +
            "• 지난 출조 맨 위 '어종별 낮·밤': 내 기록으로 낮 어종·밤 어종과 잘 잡힌 때 (출조 3번부터).")

        section(col, HelpPic.FISH, "13. 출조 종류 · 어종 (관리자)",
            "• 출조 종류(선상·해루질·워킹·원투 …)와 어종 목록은 관리자가 추가·이름 바꾸기·삭제를 하고, 모두의 앱에 똑같이 들어가요.\n" +
            "• 그룹장은 그중에서 우리 그룹에서 쓸 종류만 골라요. 종류가 하나면 자동으로 정해져요.")

        section(col, HelpPic.GROUP, "14. 💬 채팅 (전체 · 그룹)",
            "• (v6.65) 홈 맨 위 오른쪽(🔄 · ⚙ 옆) 노란 '💬' 버튼: 빨간 숫자는 안 읽은 글, 아래 작은 초록 글씨는 지금 앱을 켜 둔 사람 수예요. 그룹 창 '💬 그룹 채팅'으로도 들어가요.\n" +
            "• 채팅 창 맨 위 탭: '전체'(앱 쓰는 모든 사람) + 내가 가입한 그룹마다 하나씩. 초록 탭이 지금 보는 방이에요.\n" +
            "• (v6.64) 🔗 글에 인터넷 주소를 쓰면 하늘색 밑줄 링크가 되고, 누르면 인터넷 창이 열려요. 말풍선 아래 미리보기 카드(사진 · 제목)도 생겨요. 링크 글을 꾹 누르면 주소 복사 · 내 사이트에 담기. 전체 채팅에서 모르는 사람이 올린 링크는 조심하세요.\n" +
            "• (v6.68) 채팅 탭 순서: '전체'는 맨 앞, 그 뒤 그룹 방은 최근 글이 올라온 순서예요. 탭마다 빨간 숫자 = 안 읽은 글.\n" +
            "• 안 읽은 글은 채팅 버튼 · 탭 · 그룹 창 '그룹 채팅'에 빨간 숫자로 보여요. 그룹 채팅 새 글은 🔔 그룹 알림으로도 와요 (1시간마다 정각쯤 확인 · ⚙ 설정 '🔔 그룹 알림'에서 켜고 끄기 · 🌐 전체 채팅 알림은 처음엔 꺼짐).\n" +
            "• 전체방은 '바꾸기 ✎'로 채팅 이름을 바꿀 수 있고, '닉네임으로'를 누르면 다시 닉네임으로 보여요. 그룹방은 닉네임 그대로예요.\n" +
            "• 욕설은 자동으로 ** 로 가려져요. 내 글은 꾹 눌러 수정·삭제, 남의 글은 꾹 눌러 신고·차단(내 화면에서 안 보임).\n" +
            "• 그룹장은 그룹방 글을 지울 수 있어요. 최근 3일 글만 보여요.\n" +
            "• 운영자는 채팅 이름을 바꾼 사람도 실제 닉네임이 보이고, 글 삭제·채팅 금지를 할 수 있어요.")

        section(col, HelpPic.GROUP, "15. ✉ 1:1 문의 · 🗑 휴지통 · 📦 재고표",
            "• 맨 위 '문의': 운영자에게 1:1 문의 (나와 운영자만 보는 비공개 방, 운영자가 지우기 전까지 보관). 답장이 오면 빨간 숫자.\n" +
            "• 🗑 휴지통 ('⋯ 더보기'): 운영자·그룹장이 내 조과를 지우면 알림이 오고, 30일 안에 복구할 수 있어요. 30일이 지나면 자동으로 버려져요.\n" +
            "• 🎒 가방 (맨 아래 '🎒 가방' 탭 · 나만의 재고표): 카테고리(선상 채비 · 해루질 장비 등)를 누르면 (v6.28) 밑에서 창이 올라와요 — 위 손잡이를 위로 끌면 화면 가득, 아래로 내리거나 바깥을 누르면 닫혀요. 항목은 한 줄씩: −/＋로 수량, 호수가 있는 건 '10호 10 · 12호 10'처럼 요약되고 › 를 누르면 호수별로 펼쳐져요. 항목을 꾹 누르면 ✎ 수정(이름 · 비고 · 호수 · 부족 기준) · ▲▼ 순서 · 🗑 삭제. 카테고리 줄의 ✎ · 🗑 는 그대로예요.\n" +
            "• 그룹: 그룹 이름 옆 작고 흐린 AK1 같은 3자리 번호로 같은 이름 그룹을 구분해요. 그룹장은 대표 이미지를 올릴 수 있어요. 그룹원은 그룹 화면 맨 아래 빨간 '그룹 탈퇴'로 나갈 수 있어요 (그룹 채팅에 알림).\n" +
            "• 그룹 만들기는 운영자가 허용한 사람만 할 수 있어요 (✉ 문의로 요청). 초대 코드 가입은 누구나.\n" +
            "• 그룹 채팅방은 한 달 보관, 그룹장은 그룹 채팅방을 비울 수 있어요.\n" +
            "• (v6.59) 🌊 물 가는 쪽: 선상일 때 물흐름 막대 아래에 3시간마다 물 가는 방향 화살표(해류 예보 · 칸 약 8km · 대충). 풍돛 배는 이 방향과 바람 방향을 비교해 물살 센 시간도 선수 · 선미 · 비슷으로 보여 줘요 (못 받으면 '?').\n" +
            "• (v6.56) ⛴ 자리 예상 배 고르기 [풍 없음 | 물닻 | 풍돛]: 물닻(뱃머리 물 낙하산) 배는 거꾸로(바람 셈 → 선미 · 물살 셈 → 선수). 풍돛(선미 돛) 배는 바람 셈 → 선미 · 물살 셀 땐 '?' (물이 바람과 같은 쪽이면 선미 · 반대면 선수).\n" +
            "• (v6.34) ⛴ 선수 · 선미 자리 예상: 물살이 약한 날(무시 · 조금)도 바람이 2.5m/s 이상 불면 배가 바람에 밀려 선수가 앞장 → '선수'. 물살이 바람보다 확실히 세면 '선미'. 둘이 겨루거나 둘 다 거의 없으면 흐린 '비슷'. 막대 아래에 그날 요약 한 줄.\n" +
            "• (v6.46) 🗺 권역 낚시환경 (⋯ 더보기 · 퀵바 '권역'): 진짜 해안선 지도에 권역 16곳 · 오늘 ~ 7일 뒤. 위 탭 🌤 출조환경(바람 · 돌풍 · 파고 · 비 · 오늘 풍랑 특보) ↔ 🎣 예상조과(물세기 · 수온 · 이틀 새 수온 변화 · 게시판 최근 7일 조과 · 고른 어종 기준)로 점 색이 바뀌어요. 점을 누르면 카드에 '왜 이렇게?' 이유 + [이 권역 물때 · 날씨 자세히]. ☰ 목록 = 좋은 순 · ☆ 즐겨찾기 맨 위. 대충 계산이라 배와 포인트에 따라 달라요.\n" +
            "• (v6.50) 📱 앱에 뜨는 새 소식은 퀵바 위젯에도 떠요: 👥 그룹 칸 '● 새 소식 N' · '📅 내일 출조!' · 🟢 출조중 칸(나나 그룹원이 출조 중이면 🟢 · '나 + N명') · 💬 채팅 '● 새 글 N' · 위 줄 '✉ 답장 N' · '⬆ 업데이트' · 물때 칸과 물때 위젯에 '⚠ 풍랑주의보' 같은 기상 특보. 앱을 열 때 · 🔄 새로고침 · 정각 확인 때 바뀌어요.\n" +
            "• (v6.50) 🌡 실측이 없는 날의 '예상' 수온도 최근 실측에 맞춘 보정을 이어 써요 (먼 바다 예측은 해안 앞과 몇 도씩 달라서). 📷 권역 낚시환경 제목 줄 카메라 버튼 = 지금 화면을 사진 한 장으로 찍어 보내기.\n" +
            "• (v6.49) 📷 채팅 사진을 눌러 크게 본 뒤 옆으로 밀면 그 방의 다른 사진으로 넘어가요 (왼쪽으로 밀기 = 아래 · 나중 사진 · 오른쪽으로 밀기 = 위 · 먼저 사진). 살짝 누르면 닫혀요.\n" +
            "• (v6.62) 👀 그룹 채팅방 말풍선 옆 노란 숫자 = 아직 안 읽은 그룹원 수 (누르면 누가). 모두 읽으면 사라져요. 앱을 업데이트 안 한 그룹원은 읽어도 안 읽음으로 셀 수 있어요. 🌐 전체 채팅엔 없어요.\n" +
            "• (v6.48) 💬 퀵바 위젯 채팅 칸에 안 읽은 글 수(빨간 '● 새 글 N' · 앱 아래 채팅 숫자와 같음). 그룹 채팅 알림은 '아직 안 읽은 글'이 있으면 🔄 새로고침 · 정각 확인 때 떠요 (같은 글로 계속 울리진 않고 · 채팅방을 열어 읽으면 사라져요). 🌐 전체 채팅 알림은 ⚙ 설정 🔔 그룹 알림에서 켜요 (처음엔 꺼짐).\n" +
            "• (v6.47) 🔄 퀵바 위젯 위 줄 새로고침 버튼(옆 시각 = 마지막 확인): 누르면 그룹 소식(출조 중 · 채팅 · 공지 · 일정 · 참석)을 바로 확인해 새 소식은 위쪽 알림으로 보여 줘요. 1시간마다 자동 확인은 그대로예요. 위젯을 세로로 2줄 이상으로 늘려야 위 줄이 보여요.\n" +
            "• (v6.46) 📱 위젯 새 모양: 🌊 물때 위젯 왼쪽에 날짜 · 요일, 물세기 막대, 다음 만조/간조까지 남은 시간, 날씨 · 바람. 세로로 크게 늘리면 하루 물때 그래프(지금 · 만조 간조 · 해 뜨고 지는 시각). ⚡ 퀵바 위젯은 위에 날짜 · 물때 한 줄 + ⚡(퀵바 설정) · 한 줄 4칸 색 동그라미 · 출조중 칸에 '아무도 없음 / N명'.\n" +
            "• (v6.36) 👥 그룹 창: 초록 그룹 카드(또는 오른쪽 위 '🔄 변경')를 누르면 밑에서 내 그룹 목록이 올라와 바로 바꿔요. 카드 아래 노란 📢 공지 칸에 공지 내용이 보이고 누르면 공지 창. 🔖 그룹 사이트 메모 = 그룹원이 같이 보는 예약 사이트 · 카페 주소 목록 (추가는 누구나 · 수정 · 삭제는 올린 사람과 그룹장 · '＋ 내 사이트에 담기'로 내 🌐 자주 가는 사이트에 복사).\n" +
            "• (v6.74) 🗺 그룹 지도: 그룹 창 [🗺 그룹 지도]를 누르면 그 그룹에 공유한 포인트만 전부 하늘색 별로 보여요. 위 [☰ 포인트 N개]로 목록을 보고 누르면 그 자리로 가요. 여기서 [📌 포인트 꽂기]를 누르면 처음부터 이 그룹 공유로 저장돼요. 그룹원이 새 포인트를 올리면 버튼에 'NEW', 그룹 새 소식에 '포인트'(하늘), 아래 '그룹' 탭 · 위젯 그룹 칸 숫자에 같이 세고, 🔔 그룹 알림 '📌 그룹 새 포인트'로도 알려 줘요 (그룹 지도를 열거나 그 포인트를 누르면 꺼짐).\n" +
            "• (v6.66) 🔖 그룹 사이트 메모 📁 묶음: 그룹장이 '🚤 배 선단 · 🛒 채비 구입'처럼 묶음을 만들면, 처음엔 묶음 제목만 보이고 누르면 커튼처럼 펼쳐져요. 사이트 줄을 누르면 바로 열리고, 꾹 누르면 내 사이트에 담기 · 주소 복사 · 다른 묶음으로 옮기기 · 고치기 · 순서 · 지우기. 묶음을 지우면 안의 사이트는 '📌 기타'로 가요. (v6.67) 줄마다 🌐 주소도 보이고, 새 그룹엔 '🚤 선단 사이트' 묶음이 처음부터 있어요.\n" +
            "• (v6.36) ⏰ 일정 글마다 [📢 공지에 올리기] — 그룹원 누구나 · 올리면 '✓ 공지에 올라감'. 공지에서 [내리기]는 올린 사람과 그룹장.\n" +
            "• (v6.32) 📷 물때 사진 찍기: 물때 창 맨 위 제목 줄 오른쪽 카메라 그림을 누르면 그날 물때 그래프 · 물세기 · 물흐름 · 날씨 · 바람 · 파도 · 수온까지 스크롤 아래 전부를 긴 사진 한 장으로 찍어요. 갤러리 '조과일지' 폴더에 저장되고 '📤 보내기'로 카톡 · 문자에 바로 보낼 수 있어요.\n" +
            "• (v6.31) ⛴ 선수 · 선미 자리 예상 (대충 · 선상낚시일 때): 물때 창 시간별 물흐름 막대 위에 3시간마다 '선수'(주황) / '선미'(파랑). 그 시각 바람이 물살보다 세면 가벼운 앞(선수)이 밀려 앞장 → 선수, 물살이 세면 무거운 뒤(선미)가 끌려 앞장 → 선미, 둘이 비슷하면 흐린 '비슷' (v6.34부터 물살이 약해도 바람이 2.5m/s 이상이면 '선수'). 배와 선장님에 따라 달라요.\n" +
            "• (v6.31) 🌡 지난 날짜 실측 수온: 오늘 · 어제 실측 수온을 받으면 관측소별로 폰과 서버에 저장해서, 며칠 지나도 '실측'으로 보여요 (2026.11.17부터 쌓여요 · 아무도 안 받은 날은 예상만).\n" +
            "• (v6.31) 📱 위젯 추가 창에 진짜 위젯 모양이 미리 보여요.\n" +
            "• (v6.30) ⚡ 퀵바 위젯: 앱 퀵바에 넣은 칸이 홈 화면 위젯에도 같은 순서로 보여요. 누르면 앱이 켜지며 그 화면이 바로 열리고, 🔋 절약 칸은 앱을 안 열고 위젯에서 바로 켜고 꺼요 (켜지면 파랗게 ●). 맨 끝 '⚡ 설정' = 퀵바 설정. 세로로 늘리면 두 줄(10칸).\n" +
            "• (v6.30) 📱 앱에서 바로 위젯 추가: ⚡ 퀵바 설정 맨 위 '홈 화면에 퀵바 위젯 추가' · ⋯ 더보기 '홈 화면에 위젯 추가 (퀵바 · 물때 · 가방)'. 폰이 '추가할까요?' 물으면 추가 → 홈 화면 빈 곳에 놓여요 (꾹 눌러 옮기기). 홈 화면 앱이 지원 안 하면 손으로 넣는 법을 알려 줘요.\n" +
            "• (v6.62) 📤 게시판에 아직 안 올린 내 출조가 있으면 걸러 보기 아래 주황 칸 '내 출조 N개가 아직 게시판에 없어요' → 줄마다 [공개] · '전부 대략 위치로 공개' · '다시 보지 않기'. ⚙ 설정 '📰 전체 게시판 · 출조 끝나면 늘 공개'를 대략/정확으로 해 두면 출조 끝낼 때 묻지 않고 올려요 (사진은 빼고).\n" +
            "• (v6.29) 📰 전체 조황 · 포인트 게시판: 출조 종류는 글자 탭(고른 것 주황 밑줄 · 옆으로 밀기). 기간은 📅 날짜 칸을 누르면 밑에서 달력이 올라와요 — 시작일 → 끝일을 누르고 '이 기간으로 보기' (주황 점 = 출조 글 있는 날 · 오늘 · 이번 주 · 이번 달 · 지난달 빠른 선택). 옆 '전체 기간' 버튼. 마지막으로 고른 기간을 기억해요 (처음엔 최근 1개월).\n" +
            "• (v6.29) 게시판 글의 그룹 이름은 그룹 고유 번호로 찾아서, 그룹장이 이름 · 그림을 바꾸면 예전 글에도 바뀐 이름이 보여요.\n" +
            "• (v6.29) 어종 이름 오타 알아보기: 새 어종을 적을 때 '니ㅏㄱ지'처럼 자판이 꼬이면 \"혹시 '낙지'인가요?\" 하고 물어봐요. 이미 오타로 들어간 기록도 그림은 비슷한 어종(낙지)으로 보여요. 출조 기록의 '어종 이름 바꾸기' 목록 맨 위에도 비슷한 어종이 나와요.\n" +
            "• (v6.29) 🎒 가방 그림에 가슴장화 추가 (이름에 '가슴장화' · '웨이더'가 있으면 자동).\n" +
            "• (v6.26) 그룹 창의 '달력 · 멤버 · 그룹 관리 · 초대'를 네 칸으로 나눴어요: 📅 출조 달력 · 👥 멤버 · ✉ 초대(초대 코드 · 복사 · 카톡 · 새 코드) · ⚙ 그룹 관리(대표 이미지 · 이름 · 공지 · 종류 · 그룹 바꾸기 · 그룹장 넘기기 · 삭제 · 탈퇴).\n" +
            "• (v6.25) 📷 채팅 · 운영자 1:1 문의에 사진 보내기: 입력칸 왼쪽 📷 → 사진 고르기 (입력칸에 적은 글은 사진 설명으로 같이). 앱이 작게 줄여 보내고 위치 정보(GPS)는 빠져요. 채팅엔 작은 사진, 누르면 크게. 하루 20장까지 · 지우기 · 신고는 글과 같아요.\n" +
            "• 물때 그래프(오늘): '지금' 선이 가운데에 고정되고 앞뒤 12시간이 보여요. 손가락으로 밀면 앞뒤로 움직이고 '↺ 지금으로'로 돌아와요.\n" +
            "• 지난 출조·전체 조황: 카드를 꾹 누르면 체크박스가 생겨요. 맨 위 '전체 선택', 맨 아래 '선택한 N개 삭제(내리기)'.\n" +
            "• 처음 켤 때 위치·개인정보 동의가 나와요. ⚙ 개인 설정에서 다시 보고, '같이 출조 중 공유'는 끌 수 있어요.\n" +
            "• 설명서는 '⋯ 더보기'의 '사용 설명서'에서 열어요.")

        section(col, HelpPic.GROUP, "16. 퀵 버튼 · 그룹 이미지",
            "• 1·2번 큰 카드 아래 '＋ 어종 추가'로 어종 버튼을 원하는 만큼 만들어요 (해루질·원투용 5~6개 등). 출조 종류마다 따로 저장돼요.\n" +
            "• '⚙ 퀵 버튼 관리'에서 버튼마다 크기(작게·보통·크게)·색·순서(▲▼)를 바꾸고, ✎로 어종 변경, 🗑로 삭제해요.\n" +
            "• 퀵 버튼은 터치로만 기록해요 (리모컨·워치는 1·2번만). 꾹 누르면 그 어종 마지막 기록이 −1 돼요.\n" +
            "• 그룹장이 올린 대표 이미지가 메인 맨 위(조과일지 왼쪽), 그룹 창, 그룹 목록, 채팅 탭에 보여요. 이미지가 없으면 🚤 그림.\n" +
            "• 그룹 창의 초록 그룹 카드(또는 오른쪽 위 '🔄 변경')를 누르면 밑에서 내 그룹 목록이 올라와 그룹을 바꿔요. 그룹원은 ⚙ 그룹 관리 맨 아래 빨간 '그룹 탈퇴'로 나갈 수 있어요.\n" +
            "• 출조 종료 창에서 올릴 그룹을 하나씩 체크해 원하는 그룹에만 올려요 (기본: 지금 그룹).\n" +
            "• 가방: 폰에 바로 저장돼요. 폰 바꿀 때를 대비해 ⚙ 개인 설정 '💾 모든 데이터 백업하기'를 눌러 두세요 (가방은 서버에도 같이 저장). 부족 기준보다 적으면 빨갛게 표시돼요.\n" +
            "• (v6.23) 🌐 자주 가는 사이트 (⋯ 더보기 · 퀵바 '사이트' · v6.24에 '선사'에서 이름 바뀜): 배 이름 · 예약 사이트 주소 · 전화 · 메모를 저장해 두고 [🌐 열기]로 인터넷 창(크롬 등)에서 바로 예약. 📞 전화 · ✎ 수정 · 🗑 삭제 · ▲▼ 순서. 출조 기록의 배 이름과 같으면 기록 화면에 '🌐 예약 사이트 열기'도 나와요. 💾 백업에 같이 들어가요.\n" +
            "• (v6.75) 🚤 선상 빈자리 (⋯ 더보기 · 퀵바 '빈자리'): ① (v6.78) 주소를 안 넣어도 고른 날짜의 **선상24 전체 배**가 나와요 (30척씩 · 맨 아래 [🌐 선상24 더 보기]) · [📍 지역]으로 권역(여러 개) · [🐟 어종]으로 어종을 고르면 그 배만 찾아요 · [⚙ 선단]에서 '🌐 선상24 전체 배'를 끄면 내 선단만. 자주 타는 선단은 [⚙ 선단]에 선단 홈페이지 주소(예: sungbin.sunsang24.com)를 넣으면 지역과 상관없이 늘 보이고 물때까지 나와요 (🌐 자주 가는 사이트에 선상24 주소가 있으면 추천으로 나와요). ② 위 [📅 날짜 ▾]를 누르면 달력이 올라와요(v6.77 · 양옆 ‹ › = 하루씩). 날짜를 누르면 그날 나가는 배 · 어종 · 운항 시간 · 물때 · 남은 자리(막대 · 3자리 이하는 노랑 '곧 마감')가 나와요. 달력 날짜 아래 초록 숫자 = 조건에 맞는 빈 배 수. ③ [🐟 어종]은 여러 개 눌러 고르고 [✓ 보기]. [👥 N자리 이상]은 같이 가는 사람 수 — 남은 자리가 그보다 적으면 빈 배로 안 세요. [⚙ 필터] = 정렬(자리 많은 순 · 출항 빠른 순 · 이름 순) · 빈자리 있는 배만 · ⭐ 즐겨찾기 맨 위. ④ 배 카드 ☆ 를 누르면 ★ 즐겨찾기 → 맨 위 '⭐ 즐겨찾기' 칸. [예약 ›] = 선상24 그 선단 예약 화면(예약은 선상24에서). ⑤ 마감된 배는 [🔔 자리 나면 알림] — 그 날 그 배에 고른 자리 수 이상이 나면 알림이 와요(누르면 예약 화면). 걸어 둔 동안만 내 폰이 15분마다 확인해요 (안드로이드가 몇 분 늦출 수 있고 · 취소 자리는 금방 차서 놓칠 수 있어요). 위 [🔔 N]에서 걸어 둔 목록 · 지금 확인 · 끄기 · 날짜가 지나면 저절로 지워져요. 자리가 나면 퀵바 '빈자리' 칸 · 홈 화면 퀵바 위젯에 '🔔 자리 남'. (v6.76) 🔔 알림은 관리자가 허락한 분만 쓸 수 있어요 — 허락이 없으면 카드에 🔒 알림 · ✉ 1:1 문의로 요청 · 허락이 빠지면 걸어 둔 알림도 꺼져요. (v6.80) 🛥 개인 배 사이트: [⚙ 선단] 아래 '🛥 개인 배 사이트'에서 거북섬 헌터호를 넣으면 체험별 날짜 · 남은 자리가 같이 나오고 🔔 알림도 돼요 (다른 개인 사이트는 ✉ 문의로 주소를 알려 주시면 맞춰 넣어요). (v6.84) 선단 홈페이지를 찾은 배는 [예약 ›]이 바로 그 선단 예약 화면이에요 (선상24 창은 카드 꾹 메뉴 · v6.88 고른 날 그 배 예약 화면으로 바로). (v6.82) 🌐 마감된 배 카드 아래 [🌐 배 사이트] = 그 배 선단 홈페이지(조황 글에서 찾은 주소 · 선단에 따라 로그인 없이 예약돼요) · [📞 전화] · [밴드]. 카드를 꾹 누르면 메뉴: ＋ 내 선단에 넣기(그 선단 다른 배까지 보여요) · 주소 직접 넣기(못 찾았거나 틀렸을 때) · 배 이름 검색 · 예약 화면. [🐟 어종] · [📍 지역]은 여러 개 눌러 고른 뒤 [✓ 보기] (창을 닫아도 고른 대로) · (v6.83) 무리 이름 옆 [서해안 전체] 같은 버튼 = 그 무리 한 번에 고르기 · 다시 누르면 빼기. (v6.85) 🔎 고르기 줄 맨 앞 🔎 = 배 이름 찾기 (날짜 · 지역 · 어종과 상관없이 · 안 읽은 배도 이름으로 · 그날 안 나가면 '다음 출항 ›' 누르면 그 날로 · 최근 찾은 배 기억). (v6.90) ⚓ 🔎 에 항구 이름(마검포항 · 드르니항 · '항' 빼고도)을 치면 그 항구 선상24 · 더피싱 배가 고른 날짜 카드로 나와요 · 아래 ⚓ 항구 이름 추천. 같은 배가 선상24 · 더피싱 · 개인 사이트에 같이 있으면 한 카드로 합치고 카드에 [선상24] [더피싱] [개인 사이트] 꼬리표 · 다른 곳 예약 버튼(남은 자리)이 같이 나와요. (v6.85) 🎣 더피싱: [⚙ 선단] → [🎣 더피싱 선단 고르기](지역 · 이름으로 찾기 · 누르면 내 선단)나 ○○.thefishing.kr 주소를 넣으면 그 선단 배 · 낚시 종류 · 남은 자리 · [예약 ›](선단 예약현황) · 🔔 알림이 선상24 선단처럼 나와요. 더피싱 목록은 앱에 기본으로 들어 있어요(v6.89 · 배 678척 · 선단 343곳) · 관리자가 새로 모으면 그걸로 바뀌어요. (v6.86) 카드 왼쪽 배 사진(누르면 크게) · 노란 금액 · 📝 조황 N(그 배 조황 글 수 · 최근 글 · 누르면 목록) · 운항 시간 · 🌊 물때 · 📢 그날 공지 · 🕙 아직 안 열린 날은 예약 오픈 시각 + [🔔 열리면 알림](관리자 허락) · 아래 줄 📞 전화 · 밴드 · 📝 조황 · 👍👎 = 우리 앱 사용자 인기도(한 사람 한 배에 한 표 · 다시 누르면 취소 · 좋아요가 많으면 이름 옆 🔥). [⚙ 필터]에 🕐 출항 시간대(새벽 · 오전 · 오후 · 야간 · 여러 개) · ⏱ 운항 시간(짧게 · 보통 · 종일) — 시간 모르는 배는 숨기지 않아요. 날짜 버튼 · 달력에 그날 물때. (v6.91) 카드는 처음 20척만 보이고 맨 아래 [⬇ 더 보기]로 20척씩 더 · 고르기 줄 [↕ 정렬] = 자리 많은 순 · 출항 빠른 순 · 이름 순 · 📝 조황 많은 순 · 🕘 최근 조황 순(조황 날짜를 받아 오며 순서가 바뀌어요) · [⚙ 필터 · N] = 빈자리만 · 즐겨찾기 맨 위 · 출항 시간대 · 운항 시간(켠 개수). 🔔 자리 알림을 누르면 그 날 그 배 예약 화면이 바로 열려요. 🔎 배 이름으로 찾으면 더피싱 배도 그 선단 일정을 바로 읽어 카드로 나와요(카드 꾹 = 내 선단에 넣기). 더피싱 선단 화면에 있는 배는 목록에 없어도(테티스호 등) 한 번 읽으면 기억해서 찾기에 나와요. [⚙ 선단] 아래 '📌 관리자가 넣은 배'는 모두에게 기본으로 같이 보여요(스위치로 끄기). (v6.92) 이제 선상 빈자리는 **선단 홈페이지**(○○.sunsang24.com · ○○.thefishing.kr · 개인 사이트) 일정만 읽어요 — 내가 넣은 선단 · 관리자가 넣은 배 · 🔎 배 이름 · 항구로 찾은 배. 선상24 · 더피싱 전체 목록(사진 · 조황 수 · 공지 · 오픈 시각 포함)은 관리자가 허락한 분에게만 고르기 줄 [🚤 선상24] [🎣 더피싱] 버튼이 생겨요(켜면 보이고 끄면 안 보여요 · 🎣 더피싱은 📍 지역을 고르면 그 지역 선단 10곳까지). 선단 주소를 모르는 배는 찾기에 안 나와요. 🔎 찾기는 따로 빠른 통로로 읽어서 몇 초 안에 나오고, 15초 넘게 못 읽으면 '⚠ 못 읽었어요 · 눌러서 다시 ↻'. 선단 홈페이지 배 카드에는 📝 최근 조과(그 배 글 · 없으면 선단 글) 한 줄 · 아래 [📝 조과] = 조과 글 목록(이 배 글 먼저) · 글을 누르면 선단 홈페이지 원래 글이 열려요. (v6.95) 📍 지역을 고르면 그 지역 선단 홈페이지(선상24 선단 · 더피싱 선단 · 약 1,200곳 중 그 지역)의 배를 모두 읽어 보여 줘요 — 고른 날 하루치만 읽어서 가볍고, 6곳씩 읽히는 대로 카드가 나와요(위에 '📍 선단 N곳 중 M곳 읽음'). 처음엔 물때 창에서 고른 지점과 가까운 지역이 골라져요. 지역을 여러 개 고르면 오래 걸려요. ※ 공식 기능이 아니라 선단 페이지를 읽는 방식이라 사이트가 바뀌면 잠시 안 될 수 있어요.")

        section(col, HelpPic.GROUP, "17. 출조 시작·완료 · 그날 날씨",
            "• 출조 시작 창에서 지금 그룹의 출조 종류를 눌러 고르고, 배 이름·포인트와 항구·주요 장소를 적어요.\n" +
            "• 출조 완료 창: 올릴 그룹을 체크하고, 전체 게시판에 올릴 땐 이름(익명/닉네임)과 함께 보일 그룹을 골라요. 아래 미리보기 그대로 올라가요.\n" +
            "• '취소'는 창만 닫고 출조는 계속돼요. 초록 '✓ 완료'를 누르면 출조가 끝나요.\n" +
            "• 완료할 때 그 시간대 날씨·바람·파고·수온(실측 포함)이 출조 기록에 저장돼요. 지난 출조 화면의 '그날 날씨'에서 언제든 다시 봐요.\n" +
            "• 지도의 '📍 내 기록'은 관리자 시험용이라 관리자에게만 보여요. 앱을 닫거나 내리면 자동으로 꺼지고 지워져요.")

        section(col, HelpPic.GROUP, "18. 대표 사진 · 휴지통 · 수온 보정",
            "• 출조 완료 창의 '📸 대표 조과 사진'에서 찍거나 앨범에서 골라요. 나중에 출조 기록 화면에서 바꾸거나 이 출조 사진 중 골라도 돼요.\n" +
            "• 대표 사진은 지난 출조·그룹 출조 기록·전체 조황 카드 오른쪽에 보이고, 누르면 크게 봐요.\n" +
            "• 내가 지운 조과도 휴지통('⋯ 더보기' → 🗑 휴지통)에 30일 보관돼요. '복구'하면 그룹·전체 게시판까지 다시 올라가요.\n" +
            "• 물때 창 수온: 실측 = 관측소에서 잰 값, 보정 = 예상에 그날 실측 차이를 더한 값, 예상 = 먼 바다 예측.\n" +
            "• 물때 그래프에서 낮은 밝게, 밤은 어둡게 보여요.")

        section(col, HelpPic.GROUP, "19. 지금 출조 중 · 게시판",
            "• 그룹원이 출조 중이면 메인 '🟢 지금 출조 중 N명' 줄(초록)에 보여요. 아무도 없으면 '❌ 지금 출조 중인 사람 없음'(회색). 누르면 이름·종류·마릿수 목록, 사람을 누르면 그 사람 위치 지도.\n" +
            "• ⚡ 퀵바 · 퀵바 위젯 '출조중' 칸: 나나 그룹원 누구라도 출조 중이면 🟢(아래 '나 출조 중' · 'N명 출조 중' · '나 + N명'), 아무도 없으면 ❌.\n" +
            "• 🎨 색 약속 (v6.68): 앱 어디서든 내 것 = 주황 · 그룹 = 하늘 · 전체(게시판) = 보라예요. 포인트 핀 · 포인트 지도 점 · 지난 기록 점 왼쪽 아래 작은 색 점 · 지난 출조 배지 · 지금 출조 중 꼬리표 · 내 출조 알리기 고르기가 모두 이 색이에요.\n" +
            "• 출조 시작 창의 '내 출조 알리기'로 누구에게 알릴지 골라요 (20번 참고). 출조 중에도 메인의 초록 칩을 눌러 바꿀 수 있어요.\n" +
            "• 메인 '🌊 전체 조황 · 포인트 게시판'을 누르면 위쪽 탭으로 조황 게시판과 포인트 게시판을 오가요.\n" +
            "• 수온 칸 아래 작은 글씨는 실측한 관측소예요. 노란색이면 가장 가까운 관측소가 끊겨 다음 관측소 값을 쓴 거예요.")

        section(col, HelpPic.GROUP, "20. 내 출조 알리기 · 후기",
            "• 출조 시작 창 '내 출조 알리기': 🔒 알리지 않기 / 그룹에 알리기(알릴 그룹을 하나씩 체크) / 🌊 전체 사용자에게 공유하기.\n" +
            "• 전체 공유를 고르면 전체 조황 게시판 맨 위 '🟢 지금 출조 중'에 보여요. 이름은 게시판처럼 익명/닉네임, 위치는 동네 이름만. 내 그룹 모두에도 보여요.\n" +
            "• '지금 출조 중'은 한 줄로 접혀 있어요. 누르면 사람별 종류 · 경과 · 마릿수가 펼쳐져요.\n" +
            "• 지도의 내 이동 경로는 분홍 선이에요.\n" +
            "• 게시판 후기는 사진이 맨 위, 시각별 기록은 한 시간씩 접혀 있어요(눌러서 펼치기).")

        section(col, HelpPic.GROUP, "21. 지금 출조 중 · 위치 공유",
            "• 메인 '🟢 지금 출조 중 N명'을 누르면 내 그룹과 전체 공유한 사람이 보여요.\n" +
            "• '📍 지도 ›'가 있는 사람을 누르면 그 사람 위치(초록 점)가 가운데인 지도가 열려요. '📍 ○○ 위치로'로 언제든 그 사람에게 돌아가고, '둘 다 보기'로 나와 같이 봐요.\n" +
            "• 내 출조를 알릴 때 '📍 위치 공유하기'를 끄면 출조 중 · 마릿수만 보이고 지도엔 안 나와요.\n" +
            "• 이름 옆 꼬리표로 어디에 알리는 중인지 보여요: 하늘 꼬리표 = 그룹 이름, 보라 '전체' = 전체 공유. 목록에는 '📍 위치 공유 중 / 위치 끔'도 나와요.")

        section(col, HelpPic.GROUP, "22. 내 위치 사용 · 물때",
            "• ⚙ 개인 설정 '📍 이 앱에서 내 위치 사용'을 끄면 앱이 위치를 전혀 쓰지 않아요(경로 · 조과 위치 · 지도 내 위치 · 위치 공유).\n" +
            "• 출조 시작 때 위치가 꺼져 있으면 안내 창이 떠요. '켜러 가기'로 꺼진 것만 차례로 켜고 돌아오면 그대로 출조가 시작돼요.\n" +
            "• 물때 그래프에 '추정'이 붙은 만조·간조는 받은 자료에 빠져 있어서 앞뒤로 짐작한 거예요. '여기부터 예측'은 관측소 자료가 없어 예측으로 이은 부분이에요.")

        section(col, HelpPic.GROUP, "23. 그룹 출조 기록 내리기",
            "• 그룹 출조 기록에서 카드를 누르면 '🗑 그룹에서 내리기'가 있어요. 내 글은 누구나, 그룹장은 모든 글을 내릴 수 있어요.\n" +
            "• 카드를 꾹 누르면 체크박스가 생겨 여러 개를 골라 한 번에 내릴 수 있어요(전체 선택 · 맨 아래 버튼).\n" +
            "• 그룹에서만 내려가고 올린 사람 폰의 기록은 그대로예요. 남의 글은 휴지통에 30일 보관돼요.\n" +
            "• 그룹 창 '🎣 출조 종류 · 지금: ○○'를 누르면 종류를 고를 수 있어요.")

        section(col, HelpPic.GROUP, "24. 서버 절약",
            "• 게시판 · 그룹 출조 기록은 한 번 받은 글을 폰에 기억하고 새로 올라온 글만 받아요. 남이 지운 글은 몇 시간 뒤에 사라질 수 있어요.\n" +
            "• '지금 출조 중' · 채팅 접속 인원은 3분마다 새로 받아요.")

        section(col, HelpPic.GROUP, "25. 내 어종 목록 · 새 글",
            "• 버튼 어종을 고르는 창 맨 아래 '⚙ 내 어종 목록 관리'에서 필요 없는 어종을 지우거나(내 폰에서만), 지운 어종을 다시 보이게 하거나, 나만 쓰는 어종을 추가할 수 있어요. 업데이트해도 그대로예요.\n" +
            "• 그룹 출조 기록은 처음 열면 '🆕 새 글'(아직 안 본 글)부터 보여요.\n" +
            "• 한 번 본 사진은 폰에 저장돼서 다시 받지 않아요(데이터 · 서버 절약).")

        section(col, HelpPic.TIDE, "26. 그때 날씨 · 실측 조류",
            "• 후기(전체 게시판 글)와 그룹 출조 기록에도 그 출조 때 날씨(기온 · 하늘 · 바람 · 파고 · 수온)가 한 줄로 붙어요. 누르면 시간별 표.\n" +
            "• 물때 창 위쪽 '🌊 실측 조류 (지금)': 가까운 관측소에서 지금 잰 유향(물이 흘러가는 방향) · 유속(cm/s · 노트)과 세기(약함 · 보통 · 셈)예요. 유속계가 있는 관측소만 나와요.\n" +
            "• 서해는 밀물 때 대체로 육지 쪽(동 · 북), 썰물 때 바다 쪽(서 · 남)으로 흘러요.")

        section(col, HelpPic.MAP, "27. 조과 위치 정확도",
            "• 카드를 누를 때 20초 안에 잡힌 GPS가 있으면 그 자리로 저장돼요.\n" +
            "• GPS가 없으면(실내 · 신호 약함) 폰이 아는 위치로 일단 저장하고, 누른 뒤 1분 동안 GPS를 2초마다 재서 잡히면 정확한 위치로 바꿔 넣어요.\n" +
            "• 그래도 못 잡았으면 이동 경로 앞뒤 GPS 점으로 그 시각 위치를 다시 계산해요 (출조를 끝낼 때도 한 번 더).\n" +
            "• 지도에서 조과를 누르면 '(대략 위치 ±m)' · '(경로로 계산한 위치)'로 어떻게 잡힌 위치인지 보여요.\n" +
            "• 와이파이 · 기지국 위치나 오차가 큰 위치(±50m 넘게)는 이동 경로와 위치 보정에 쓰지 않아요. 순간이동처럼 튄 점도 버려요.\n" +
            "• 대략 위치로 잡힌 조과는 지도에서 흐린 점 + 주황 오차 원으로 보여요.\n" +
            "• 건물 안에서는 GPS가 거의 안 잡혀요. 위치 테스트는 밖에서 해 주세요.")

        section(col, HelpPic.MAP, "28-1. 포인트 지도 · 원 그려서 분석",
            "• 전체 조황 · 포인트 게시판 → '📍 전체 포인트 게시판' 맨 위 '🗺 포인트 지도'를 눌러요.\n" +
            "• ☑ 전체 포인트 = 모두가 공개한 조과, ☑ 나만의 포인트 = 게시판에 안 올린 것까지 내 폰 기록 (나만 보여요). 하나만 또는 둘 다 체크할 수 있어요.\n" +
            "• (v6.62) 📊 원 안 분석 바로잡음: 같은 출조가 그룹 · 전체 게시판에 둘 다 있으면 한 번만 셈 · 1시간 평균은 원 안에서 처음~마지막으로 잡은 시간(+앞뒤 30분)으로 · 만조/간조 칸은 앞뒤 3칸씩 · 자정 넘긴 출조는 그날 물때로 · 수온은 실측만 · 바람 · 파고는 실측(없으면 예보) · 🧭 기압 변화 줄 추가 · '달' → '월' · '6~8물 (사리 한가운데)'.\n" +
            "• '⭕ 원 그리기'를 누르고 지도를 누르면 원이 생겨요. 분홍 점을 끌면 크기가 바뀌고, 지도를 다시 누르면 원이 옮겨져요.\n" +
            "• '📊 이 원 안 분석 보기': 어종마다 1시간 평균, 잘 나온 물때 · 물세기 · 만조간조 기준 · 시간대(일출 · 일몰 기준) · 수온 · 바람 · 파고 · 월을 정리해 줘요.\n" +
            "• 아래 '조건별 자세히'에서 어종과 조건을 골라 막대로 비교해요. 👑 = 가장 잘 나온 조건, 흐린 칸 = 출조 3번 이하라 데이터 부족.\n" +
            "• 위에서 고른 출조 종류 · 기간(📅 날짜 · 전체 기간)이 그대로 적용돼요.\n" +
            "• 포인트 게시판 목록은 출조 한 건씩 나와요(1시간 평균 마릿수 순). 어종 칩을 고르면 그 어종 기준 순위, '가까운 순'은 내 위치에서 가까운 출조부터. 누르면 그 출조 지도 · 조과 · 사진 · 날씨.")

        section(col, HelpPic.GROUP, "28-2. 실시간 조과 지도 (권한)",
            "• 관리자가 권한을 준 사람은 '🟢 지금 출조 중'에서 사람을 누르면 그 사람의 이동 경로와 잡은 자리별 마릿수까지 보여요. 권한이 없으면 지금 위치 점만 보여요.\n" +
            "• 그룹에 알리면 그룹원(권한 있는 사람)에게, 전체 공유는 '🗺 전체에도 정확한 위치 · 조과 지도 공유'를 켰을 때만 보여요.\n" +
            "• 서버 절약: 잡을 때와 3분마다만 올리고, 보는 사람은 그 지도를 열어 둔 동안만 받아요.")

        section(col, HelpPic.MAP, "28-3. 🦀 해루질 참고용 (마을어장 · 양식장 · 위험 구역)",
            "• 지도(출조 지도 · 포인트 지도) 위쪽 '☐ 해루질 참고용'을 누르면 켜져요(☑). 끄면 아무것도 안 보이고 알림도 없어요.\n" +
            "• 켜면 확대했을 때 🐚 마을어장(주황) · 🦪 양식장(파랑) · 🐟 수산자원관리수면(초록) · ⚠ 사고 위험 구역(빨간 점선)이 색으로 보여요. 누르면 무엇인지 · 주의할 점.\n" +
            "• 출조 중 켜 두면, 그 구역 안으로 들어갈 때 진동 + 알림으로 알려줘요.\n" +
            "• 낚시는 이 구역에서도 할 수 있어요. 해루질(채취) 분쟁을 피하려는 참고용이고, 실제 경계 · 허용 여부는 현장 안내판 · 어촌계 · 지자체가 우선이에요.\n" +
            "• 관리자: 🛠 관리자 페이지 → '🦀 해루질 참고 구역'에서 공공데이터포털 CSV 올리기 · 지도에서 직접 그리기 · 고치기 · 지우기.")

        section(col, HelpPic.FISH, "28. 어종 그림 · 앱 아이콘",
            "• 어종 그림 70종을 새 그림으로 바꿨어요. 카드 이마의 이름 띠는 그대로예요. 그림이 없는 어종은 기본 그림으로 나와요.\n" +
            "• '⋯ 더보기' '📋 업데이트 내역'에서 언제 무엇이 바뀌었는지 종류별로 볼 수 있어요.")

        section(col, HelpPic.TIDE, "28-4. 메인 화면 (v3.7)",
            "• 물때 칸 첫 줄 맨 앞에 지금 위치(📍안산 등)가 보여요. 물때 칸 배경에 지금 날씨(해 · 구름 · 비 · 눈 · 천둥)가 흐리게 그려져요.\n" +
            "• (v6.65) 화면 맨 아래 탭: 🏠 홈 · 🗺 지도 · 👥 그룹 · 📒 내 조과(지난 출조 · 내 기록 보관함) · 🎒 가방 · ⋯ 더보기. 💬 채팅은 홈 맨 위 오른쪽 버튼이에요. 홈 맨 아래는 🟢 지금 출조 중 → 🌊 전체 조황 · 포인트 게시판.")

        section(col, HelpPic.MAP, "28-5. 지도 어종 그림 · 물때 창 날짜 · 자외선 (v3.8)",
            "• 모든 지도에서 조과는 어종 그림 + 마릿수로 보여요. 가까이 겹치면 하나로 묶이고 '주꾸미 외 N종'이 붙어요. 누르면 상세.\n" +
            "• 물때 창 맨 위 제목과 '날씨 · 바람 · 파도 · 수온' 제목에 지금 보고 있는 날짜가 붙어요 (오늘 = 초록, 다른 날 = 노랑).\n" +
            "• 날씨 칸 위 '☀ 자외선'은 그날 최고값(오늘은 지금 값도)과 단계예요. 기상청 시·도 단위라 받을 수 있는 날(약 3일)만 보여요.\n" +
            "• 배터리 절약을 켜면 위치는 3분 간격, 서버 올리기는 5분마다 모아서 해요. 출조 중에도 '배터리 절약' 칩을 한 번 누르면 바로 켜고 꺼져요.\n" +
            "• 관리자: 해루질 참고 구역은 '🌐 API로 받기'로 버튼 한 번에 받을 수 있어요. 올릴 때 '바꾸기'(같은 종류 예전 자료 지움) · '더하기'(합치기)를 골라요.\n" +
            "• 포인트 지도 '그룹 포인트 ▾'를 누르면 가입한 그룹 목록이 펼쳐져요. 체크한 그룹의 출조 기록 조과가 하늘색으로 보여요 (v6.68 · 내 것 주황 · 그룹 하늘 · 전체 보라). ⭕ 원 안 분석은 지금 지도에 보이는(체크한) 조과만 계산해요.\n" +
            "• 출조 중이 아닐 때 메인 '지도'는 빈 지도 + 내 위치예요. 지난 조과는 '지난 기록'을 누르면 보여요. ('📍 내 기록'은 v6.68부터 관리자 시험용이에요.)")

        section(col, HelpPic.MAP, "28-6. 🦀 해루질 참고용 (v3.9 · 개방海)",
            "• '☐ 해루질 참고용'을 누르면 매번 '참고용' 안내창이 떠요. 보일 구역(🐚🦪 어장 · ⚠ 갯골 · 웅덩이 · 🚫 낚시금지 · 제한)을 고르고 [확인]을 눌러야 켜져요.\n" +
            "• 국립해양조사원 '개방海' 자료를 지도에 보이는 곳만 자동으로 받아요. 전국이 다 나오고, 한 번 받은 곳은 30일 동안 폰에 기억해요.\n" +
            "• 구역을 누르면 면허기간(남은 기간 · 만료) · 면허번호 · 면적 · 어업방법 · 문의처가 나와요. 만료로 나와도 재면허를 받았을 수 있으니 현장 확인이 우선이에요.\n" +
            "• 관리자: 🛠 → 🦀 해루질 참고 구역 → '🔑 인증키 넣기'(개방海 '해양공간정보' 키) → '🔌 연결 확인'. 공공데이터 API는 '🌐 API로 받기' 목록에 이름 · 주소 · 종류로 추가해요.\n" +
            "• 처음 보는 바다는 '🌊 개방海 받는 중…'이 뜨고 몇 초 뒤 그려져요. 자료가 많은 곳은 조금 더 걸려요.\n" +
            "• 지도 왼쪽 세로 줄 맨 위 '🔍 장소'로 지명 · 항구를 찾아 바로 이동할 수 있어요 (최근 검색 기억 · ✕로 지우기). (v6.85) 포인트 · 지도 표시처럼 버튼 옆에 이어진 상자로 열려요 — 검색 칸에 치거나 [찾기] · 찾은 곳을 누르면 지도가 옮겨 가고 상자가 닫혀요 · ✕ 또는 버튼 다시 = 닫기.\n" +
            "• (v3.9.2) 켠 뒤 '☑ 해루질 참고용 ▾'를 누르면 바로 아래 커튼이 열려요: 보일 구역 체크(누르면 바로 바뀜) · 📥 이 화면 지역 미리 받기 · 해루질 참고용 끄기.\n" +
            "• 📥 미리 받은 지역은 바다에서 인터넷이 약해도 보여요. ⚙ 개인 설정 → '📥 오프라인 지역'에서 다시 받기 · 지우기 · 모두 지우기.\n" +
            "• 면허 종료일이 지난 곳은 회색 '⏳ 자료상 종료일 지남'으로 나와요. 23년 자료라 재면허를 받았을 수 있으니 문의처(시·군 해양수산과)에 확인하세요.\n" +
            "• '🔍 장소'는 치는 동안 비슷한 이름이 목록으로 나와요 ('한하계' → 한하계 해수욕장 · 물때 지점 포함).\n" +
            "• 글씨 · 버튼 크기는 폰 화면 너비에 맞춰 자동으로 맞춰져요 (폴드를 펴고 접어도 알아서). ⚙ 개인 설정 '📐 화면 크기' 막대로 70%~120% 직접 조절 · '↺ 자동으로 되돌리기'.\n" +
            "• (v3.9.3) 해루질 커튼은 작은 두 줄: 위는 보일 구역 칩(🐚 어장 · ⚠ 갯골 · ⚠ 인명사고 · 🚫 금지구역), 아래는 📥 이 지역 받기 · 끄기.\n" +
            "• 🔍 장소로 검색해서 옮겨 가면(해루질 참고용을 켠 경우) 그 주변을 자동으로 미리 받아요. 1인당 하루 10지역 · 최대 20곳까지 (관리자가 바꿀 수 있어요).\n" +
            "• 관리자: 커튼의 '🇰🇷 전국 받기'로 전국 해안 · 섬을 한 번에 받아요 (이어 받기). 🛠 → 🦀 해루질 참고 구역 → '📏 1인당 미리 받기 제한'에서 숫자 바꾸기.\n" +
            "• 포인트 지도 · 지금 출조 중인 사람 지도에도 🔍 장소 · ☑ 해루질 참고용이 있어요.\n" +
            "• 옆으로 밀리는 버튼 줄은 화면 밖에 더 있으면 작은 주황 › ‹ 가 떠요 (누르면 그쪽으로 밀려요).")

        section(col, HelpPic.MAP, "28-7. 🎣 출조추천 · 물때 달력 (v4.0)",
            "• '⋯ 더보기'의 '🎣 출조추천'을 누르면 달력이 떠요. 위 칩에서 볼 어종을 켜고 끄고, '＋ 어종'으로 넣고, 꾹 눌러 빼요.\n" +
            "• 날짜 칸의 어종 그림 = 그 어종이 잘 잡히는 물때인 날이에요. 그 어종 출조가 5번 넘게 쌓이면 내 기록(물세기별 1시간 평균)으로 계산하고(📊 앱 기록), 모자라면 낚시인들이 흔히 말하는 기본값(📖 기본값)을 써요.\n" +
            "• 🥅 뜰채 = 물이 많이 빠지는 날(사리 무렵) · 해루질 좋은 날. 칸 아래 막대는 물세기(초록 = 사리, 파랑 = 조금), 달 모양 · 몇 물도 나와요.\n" +
            "• 날짜를 누르면 간조 · 만조 시각과 높이, 해루질 시간, 일출 · 일몰, 월출 · 월몰, 안개, 갯벌체험지수 · 바다낚시지수(승인 뒤)가 나와요.\n" +
            "• ⚠ 내 위치 바다 구역(서해중부 등)에 풍랑 · 강풍 특보가 있으면 메인 물때 카드 · 물때 창 · 달력에 빨간 띠로 알려요.\n" +
            "• 물때 창 '만조·간조 알람'에서 🌊 밀물 시작 알림 · 🌅 일출 · 일몰 30분 전 알림을 켤 수 있어요 (출조 중에만 울려요).\n" +
            "• (v4.1) 🥅 해루질 좋은 날은 실제 물때 자료로 '그날 가장 낮은 간조가 100cm 이하'인 날이에요. 해루질 칩을 꾹 누르면 기준(60~150cm)을 바꿔요. 칸 오른쪽 위 ↓숫자 = 그날 가장 낮은 간조(cm).\n" +
            "• (v4.1) 물세기 %는 그 관측소의 1년 중 큰 사리를 100%로 계산해요 (처음 한 번 받아 두고 기억).\n" +
            "• (v4.1) 해루질 구역에 들어가면 목소리로 알려 주고, 구역마다 진동이 달라요: 갯골 · 인명사고 짧게 3번, 어장 2번, 금지구역 길게 2번. 해루질 커튼의 '🔊 음성'으로 켜고 꺼요.\n" +
            "• (v4.1) 데이터 절약: 미리 받기는 켜 둔 구역 종류만, 모바일 데이터면 먼저 물어봐요(검색 자동 받기 · 전국 받기는 와이파이에서만). ⚙ 개인 설정 '📶 이 앱이 쓴 데이터'에서 확인.\n" +
            "• (v4.1) 리모컨 따닥 연타도 다 세요. 한 번 누를 때 두 번씩 세지면 기록 방식 '리모컨' 커튼의 '느리게'를 켜세요.")
        section(col, HelpPic.TIDE, "28-8. v4.2 바뀐 것",
            "• (v4.7) 메인을 간단하게: 위쪽 버튼 줄과 아래쪽 그룹 · 메뉴 · 관리자 버튼을 화면 맨 아래 탭 6개로 모았어요 — 🏠 홈 · 🗺 지도 · 👥 그룹(새 소식 빨간 숫자 · 내일 일정 초록 점) · 📒 내 조과(v6.65까진 💬 채팅 · 지금 채팅은 홈 맨 위 오른쪽) · 🎒 가방 · ⋯ 더보기.\n" +
            "• (v4.7) ⋯ 더보기: 맨 위 큰 칸 🎣 출조추천 · ⚙ 설정 · ✉ 관리자 문의(답장 빨간 숫자), 그 아래 설명서 · 업데이트 내역 · 휴지통 · 지난 출조 · 계정, 맨 아래 🛠 관리자 페이지(관리자) · 버전.\n" +
            "• (v4.7) 물때 카드는 물때(노란색) · 지금 들물/날물(꼬리표) · 다음 만조/간조 시각 · 물세기를 강조하고, 카드 어디를 눌러도 물때 창이 열려요. 기록 방식은 '출조 시작' 바로 밑 한 줄 + 하늘색 '⚙ 바꾸기'.\n" +
            "• (v6.16) 💧 잡은 때 물살 %는 조과마다 그 자리에서 가장 가까운 관측소 물때로 계산해요 (출조 하나에 최대 3곳). 물때 그래프 · 물세기는 첫 조과 자리 기준 그대로. 물때 창에서 관측소를 직접 골라 두었으면 그 관측소로만 계산해요.\n" +
            "• (v6.15) 💧 잡은 때 물살 % = 그날 물세기 × (잡은 시각 물흐름 ÷ 그날 가장 빠를 때). 그날 물세기가 68%면 가장 빠를 때 잡은 건 68%, 물돌이 무렵은 10% 정도. 입질 시간 메모 · 시간대별 기록(마리마다) · 분석 '잡은 때 물살'에 나와요 (30% 아래 약함 · 30~60 보통 · 60 이상 셈). 오른쪽 위 '낮 88%' = 해 떠 있을 때 잡은 비율.\n" +
            "• (v6.57) 🔢 마리 수 바로 고치기: ✎ 조과 고치기를 누르면 어종마다 − 숫자 ＋ 줄이 나와요. − ＋ 로 늘리고 줄이거나 숫자를 눌러 직접 적은 뒤 [💾 저장]. 늘린 건 위치 없이 마지막 기록 시각으로 들어가고, 줄이면 그 어종의 가장 늦은 기록부터 빠져요.\n" +
            "• (v6.12) ✎ 조과 고치기를 누르면 맨 위에 '🐟 어종 이름 한 번에 바꾸기'가 나와요. 잘못 고른 어종이나 오타(예: 니ㅏㄱ지)를 골라 다른 어종으로 바꾸면 그 출조의 그 어종 기록이 전부 바뀌어요. 올린 사람 · 관리자만 할 수 있어요.\n" +
            "• (v6.10) 📰 게시판에 올릴 때 '이동 경로도 공개'(기본 켬)를 고를 수 있어요. 정확한 위치 공개일 때만 올라가고, 큰 상세 화면 · 지도 '지난 기록'에 경로와 이동 거리가 보여요. 예전에 정확 공개한 내 글은 앱을 켤 때 경로를 한 번 자동으로 올려요.\n" +
            "• (v6.9) 🏞 민물낚시: 출조 종류 '민물낚시'(또는 어종이 배스 · 붕어 등 민물 고기뿐)면 물때 대신 🌅 해 · 시간대 — 일출 · 일몰, 골든타임(일출 · 일몰 전후 1시간), 해 기준 마릿수. 출조 중 메인 카드에 '일몰까지 ○시간 · 저녁 골든타임'. 만조 · 간조 알람은 안 울려요.\n" +
            "• (v6.9) 📰 전체 게시판 글을 누르면 그룹 출조처럼 큰 상세 화면이 열려요 (경로 · 배 이름 · 이용료 금액은 게시판이라 없어요). 맨 아래 '이 사람 차단' · '공개 내리기'.\n" +
            "• (v6.9) 🗺 지도 '지난 기록': 출조마다 색이 다르고 이동 경로가 얇게 깔려요. 위 색 범례나 점의 '🗺 이 출조만 보기'를 누르면 그 출조만 진하게(잡은 순서 번호 · 시각 · 이동 거리), 나머지는 흐리게. 위 안내 줄을 누르면 다시 다 보기.\n" +
            "• (v6.24) 💾 ⚙ 개인 설정 → '💾 모든 데이터 백업하기' 버튼 하나로 정리: 항목별 크기가 보이고, 📷 사진 원본 · 🗺 받아 둔 지도는 넣을지 골라요. 설정 · 가방 · 사이트 · 리모컨 같은 작은 것은 서버에도 같이 저장돼서 새 폰에서 로그인 → '☁ 서버에서 설정 불러오기'. 받아 둔 지도 · 사진 원본은 폰 백업 파일에만 들어가요. 🦀 해루질 정보 · 물때/날씨 저장분은 다시 받으면 돼서 빠져요. 출조 기록은 지금처럼 서버에 자동 백업돼요. (가방의 '서버에 저장하기' 버튼은 이 버튼으로 합쳐졌어요)\n" +
            "• (v6.7) 💾 ⚙ 개인 설정 → 💾 백업: '폰에 백업하기' = 가방 · 앱 설정(퀵바 · 기록 방식 · 리모컨 버튼 · 화면 크기 · 알람 · 즐겨찾기 지점) · 받아 둔 지도 · 출조 기록 · 사진 원본을 파일 하나로 저장 (저장할 곳 고르기, 기본 다운로드). 폰을 바꾸면 그 파일을 옮겨 '백업 파일에서 불러오기'. 진행 중인 출조는 빠져요.\n" +
            "• (v6.6) 그룹원 '지금 출조 중' 지도 아래에 그 사람 이동 거리(km · 해리 · 출발지에서)가 나와요.\n" +
            "• (v6.4) 🔄 메인 오른쪽 위 ⚙ 왼쪽 = 업데이트 확인. 새 버전이 있으면 빨간 점이 붙고, 누르면 바로 업데이트 창 (플레이 스토어판은 스토어 화면으로). 없으면 '최신 버전이에요'.\n" +
            "• (v6.3) 🟢 그룹원 '지금 출조 중' 지도에도 '지난 기록' 버튼: 누르면 예전 조과 자리가 반투명 그림으로 깔려요 (내 기록만 · 그룹 친구 · 전체 게시판 3개월 · (v6.27) 전체 게시판 전체 기간 중 고르기 = 위 '지난 기록: … 보기 바꾸기 ▾'). 지금 그 사람이 있는 곳에서 예전에 뭐가 잡혔는지 같이 볼 수 있어요.\n" +
            "• (v5.3) ✎ 조과 고치기: 출조가 끝난 뒤 출조 상세 '시간대별 기록' 오른쪽 '✎ 조과 고치기'를 누르면, 시간대를 펼쳐 한 마리씩 ✎(시각 · 어종) · 🗑, 또는 체크(시간대 전부 고르기)해서 한꺼번에 지울 수 있어요. ＋ 조과 추가도 돼요. 고치면 올린 그룹 기록 · 순위 · 전체 게시판 공개 글(v6.1)에도 같이 반영되고 '수정됨' 표시가 붙어요. 고치기는 올린 사람과 관리자만 돼요 (관리자가 고치면 올린 사람 폰 기록도 다음에 앱을 열 때 같이 고쳐져요).\n" +
            "• (v5.2) 👥 그룹 출조 기록에서 카드를 누르면 그 사람 출조 상세가 내 기록처럼 열려요 (보기 전용 · 수정·삭제는 올린 사람만, 그룹에서 내리기는 그룹장·관리자도).\n" +
            "• (v5.2) 🎮 리모컨 버튼을 누르고 있어도 한 번만 세요. 빠르게 두 번 누르면 두 번 (길게 0.8초 누르면 마지막 취소는 그대로).\n" +
            "• (v5.2) 🗺 지도 확대 · 축소는 오른쪽 아래 ＋/－, 그 아래 ◎는 내 위치로.\n" +
            "• (v5.1) 📍 지점 검색: 물때 창 '📍 지점 · 관측소 검색'(또는 제목 아래 파란 줄)에서 '신도'처럼 섬 · 항구 · 낚시터 이름을 쳐요(카카오 검색). 고르면 물때는 그 지점에서 가장 가까운 관측소, 날씨 · 바람 · 파도는 그 지점 기준이에요. ☆를 누르면 ⭐ 즐겨찾기에 들어가고, 즐겨찾기는 ✎ 이름 바꾸기 · 🗑 지우기. '지점 해제'를 누르면 다시 내 위치 기준.\n" +
            "• (v5.1) 바람 해상 기준을 고쳤어요: 해안을 따라 미리 정한 바다 기준점(예: 신도·장봉도 앞바다) 중 가장 가까운 곳의 바람 · 파고 · 수온이에요. 표 아래에 어느 기준점인지 나와요. 관측소를 직접 고르면 날씨도 그 관측소 자리 기준이에요.\n" +
            "• (v6.62) 🛟 지금 실제 바다: 물때 창 실측 조류 아래 줄에 가까운 기상청 부이 · 등표에서 지금 잰 바람 · 파고 · 수온 · 기압(3시간 변화)이 나와요 (관측점 이름 · 거리 · 몇 시 관측). 예보와 많이 다르면 '⚠ 바람이 예보보다 N m/s 세요'처럼 알려 줘요. 항구 안 부이는 '(항구 안)', 30km 넘으면 '(멀어요)'. 선상 자리 예상(선수 · 선미)의 지금 칸도 실측 바람으로 계산해요. 해양조사원 실측 수온이 없는 날은 가까운 부이 실측으로 채워요. 바람 지도엔 지금 칸에서 흰 네모 숫자 = 실측. 권역 낚시환경 카드에도 오늘 실측 한 줄. 진행 중인 태풍(한반도 영향)은 특보 띠에 같이 나와요.\n" +
            "• (v6.53) 🌬 바람 지도: 물때 창 '날씨 · 바람 · 파도 · 수온' 제목 아래 버튼 (v6.61부터 윈디 버튼과 나란히) · (v6.54) 지도 왼쪽 세로 줄 '🌬 바람'. 바람 세기 색 · 흘러가는 선 · 칸마다 화살표 m/s. 위에서 예보(기상청 · 유럽 · 미국)를 고르고, 아래 시간 막대를 밀거나 ▶ 로 3일 바람을 봐요. 지도를 누르면 그 자리를 세 예보로 비교해요 (예보마다 1~3m/s 차이 나는 게 보통이에요).\n" +
            "• (v5.0) 🌊 물때 창 '바람 기준 [육상 | 해상]': 해상(기본)은 내 위치에서 가장 가까운 바다 칸의 바람이라 바다 위 실제 바람에 가까워요 (육지는 건물·지형에 막혀 1.5~2배쯤 약하게 나와요). 표 아래에 몇 km 앞바다 값인지 나와요. 홈 위젯 · 출조 기록 날씨도 이 기준을 따라요.\n" +
            "• (v5.0) 바람 색: 초록 = 괜찮음(5m/s 아래) · 노랑 = 주의(5~9m/s) · 빨강 = 셈(9m/s 이상). 돌풍(최대)도 5m/s 넘으면 같은 색으로.\n" +
            "• (v4.9) 앱 이름이 '조과일지'로 바뀌었어요 (기록 · 그룹 · 로그인은 그대로).\n" +
            "• (v4.9) 📱 홈 화면 위젯: 폰 홈 화면을 꾹 → 위젯 → '조과일지'. 🌊 물때 위젯은 물때 · 들물/날물 · 다음 만조/간조 · 물세기 · 날씨, 크게 늘리면 오늘 물때 그래프. 🎒 가방 위젯은 ◀ ▶로 카테고리 넘기기 · −/＋로 수량. 누르면 앱의 그 화면이 열려요. 위젯은 앱이 받아 둔 값을 써서 서버를 더 쓰지 않아요.\n" +
            "• (v4.9) 🌊 물때 창 '주간': 아래 '▼ 14일까지 더 보기'(8~14일 날씨는 흐리게 = 참고) → '▼ 21일까지 더 보기'(15~21일은 날씨 예보가 없어 물때 · 물세기 · 가장 낮은 간조 · 만조 · 일출 · ⭐ 해루질 좋은 날).\n" +
            "• (v4.9) ⚡ 퀵바: 지도 · 채팅 · 가방 · 그룹 · 설정 등 앱의 모든 메뉴를 칸으로 넣을 수 있어요. 맨 끝 '⚡ 퀵바 설정' 칸은 고정(못 빼요).\n" +
            "• (v4.8) ⚡ 퀵바: 오른쪽 위 ⚙ 옆 네모 칸. 누르면 그 화면이나 설정으로 바로 가요. 3개까지는 ⚙ 옆, 4개부터는 제목 아래 한 줄(옆으로 밀기). 칸을 꾹 누르거나 ⋯ 더보기 → '⚡ 퀵바 설정'에서 칸마다 켜고 끄고 ▲▼로 순서를 바꿔요. 위치 · 배터리 절약 칸은 누르면 바로 켜짐/꺼짐(꺼지면 흐리게).\n" +
            "• (v4.8) 🎒 가방 그림: 카테고리 ✎ · 항목 ✎ 수정 창에서 장비 그림 24종(봉돌 · 쇠 · 텅스텐 · 형광 · 막대 · 구멍 · 도래 · 컬러 · 스파이크 · 좁쌀 봉돌, 핀도래, 도래, 지그헤드, 채비, 에기, 바늘, 낚싯줄, 낚싯대, 베이트 · 스피닝 릴, 구명조끼, 쿨러, 집어등, 장갑)이나 이모지를 골라요. 안 고르면 이름을 보고 자동(예: '텅스텐 12호' → 텅스텐 봉돌).\n" +
            "• (v4.7) 어종 카드의 ✎ = 어종 바꾸기 · 리모컨 버튼을 길게(약 0.8초) 누르면 마지막 기록 취소 (예전 메인 안내 글은 여기로 옮겼어요).\n" +
            "• 🎒 가방: 카테고리 줄 오른쪽 ✎ = 이름 · 그림 · 순서(▲ 위로 · ▼ 아래로) 바꾸기, 🗑 = 삭제. 항목 카드 아래 ✎ 수정 · 🗑 삭제 · ▲▼ 순서. 세부(호수)는 수정 창에서 ✕로 지워요.\n" +
            "• 출조 시작 창: 맨 위에 취소 · 건너뛰기 · ▶ 출조 시작 버튼, 그 아래 배 이름 · 항구(나란히), 출조 종류, 내 출조 알리기.\n" +
            "• 내 출조 알리기: 처음엔 '그룹에 알리기' + 내 그룹 모두 체크. 📍 위치 공유는 위치 권한 · 앱 위치 사용이 켜져 있으면 자동 체크, 꺼져 있으면 자동 해제(누르면 켜러 가요). 한 번 출조를 시작하면 그때 고른 종류 · 알리기 · 그룹 · 위치 공유 · 배 · 항구가 다음 기본값이 돼요.\n" +
            "• 🔍 장소 찾기: 폰 주소 찾기에 더해 오픈스트리트맵 지명도 찾아요(시화호 · 섬 · 방파제 등). 물때 지역(관측소) 고르기 창에서도 지명(예: 시화호)을 치면 근처 관측소가 나와요 (v4.2.1).\n" +
            "• 물세기 % = 그날 조차(만조↔간조 높이 차들의 평균 · v6.2) ÷ 그 관측소 1년 중 가장 큰 사리 때 조차. 물세기 아래 막대 = 시간별 물흐름 세기(높고 주황일수록 셈).\n" +
            "• 창이 열리고 닫힐 때 부드럽게 움직여요 (가방은 아래에서 위로, 확인 창은 살짝 커지며, 큰 화면은 오른쪽에서).\n" +
            "• (v6.0) 🎮 미니게임(바다찌낚시 · 쭈꾸미 선상 · 랭킹 · 테스트판)은 빠졌어요.\n" +
            "• (관리자) 🛠 메뉴 '🌊 물때 관측소 찾기 · 추가 · 수정 · 삭제': 앱에 없는 국립해양조사원 관측소를 찾아 추가하면 모든 사람 앱에 바로 들어가요.")

        section(col, HelpPic.UPDATE, "29. 업데이트",
            "• 앱은 플레이 스토어로만 업데이트해요 (v6.41부터 · 예전 '앱 안에서 받기'는 없어졌어요).\n" +
            "• 메인 오른쪽 위 🔄 = 업데이트 확인. 새 버전이 있으면 빨간 점이 붙고, 누르면 플레이 스토어 화면이 열려요 (또는 앱 안에서 바로 받기). 없으면 '최신 버전이에요'. 퀵바 위젯 위 줄에 '⬆ 업데이트'도 떠요.\n" +
            "• 플레이 스토어 앱 → 프로필 → 앱 및 기기 관리에서 자동 업데이트를 켜 두면 편해요. 기록은 그대로 남아요.\n" +
            "• 관리자가 예전 버전을 막으면 업데이트해야 쓸 수 있어요. 출조 중엔 막지 않고, 출조가 끝난 뒤에 떠요.")

        col.addView(Ui.text(this, 11f, Ui.SUB, false, "버전 ${BuildConfigInfo.VERSION}"), Ui.lp(this, MATCH, WRAP, top = 20))
        setContentView(ScrollView(this).apply { setBackgroundColor(Ui.BG); isFillViewport = true; addView(col) })
    }

    /** 기능 하나 = 커튼 (제목만 보이고, 누르면 그림 + 설명 펼침) */
    private fun section(col: LinearLayout, pic: Int, title: String, body: String, image: Int = 0, image2: Int = 0) {
        val c = Ui.card(this)
        val r = Ui.row(this).apply { isClickable = true }
        r.addView(HelpPic(this, pic), LinearLayout.LayoutParams(dp(40), dp(40)))
        r.addView(Ui.text(this, 16f, Ui.TEXT, true, title), LinearLayout.LayoutParams(0, WRAP, 1f).apply { leftMargin = dp(12) })
        val arrow = Ui.text(this, 15f, Ui.SUB, true, "▸")
        r.addView(arrow, LinearLayout.LayoutParams(WRAP, WRAP).apply { leftMargin = dp(8) })
        c.addView(r)
        val inner = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; visibility = View.GONE }
        if (image != 0) inner.addView(Guide.image(this, image), Ui.lp(this, MATCH, WRAP, top = 10))
        if (image2 != 0) inner.addView(Guide.image(this, image2), Ui.lp(this, MATCH, WRAP, top = 8))
        inner.addView(Ui.text(this, 14f, Ui.TEXT, false, body).apply { setLineSpacing(0f, 1.35f) }, Ui.lp(this, MATCH, WRAP, top = 10))
        c.addView(inner)
        r.setOnClickListener {
            val open = inner.visibility != View.VISIBLE
            inner.visibility = if (open) View.VISIBLE else View.GONE
            arrow.text = if (open) "▾" else "▸"
        }
        col.addView(c, Ui.lp(this, MATCH, WRAP, top = 10))
    }

    private fun tip(col: LinearLayout, s: String) {
        val c = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL; isBaselineAligned = false
            background = Ui.bg(this@HelpActivity, Color.parseColor("#2A2310"), 14, Ui.ORANGE)
            setPadding(dp(14), dp(12), dp(14), dp(12))
        }
        c.addView(HelpPic(this, HelpPic.EGI), LinearLayout.LayoutParams(dp(56), dp(56)))
        c.addView(Ui.text(this, 14f, Color.parseColor("#FFE2C2"), false, s).apply { setLineSpacing(0f, 1.3f) },
            LinearLayout.LayoutParams(0, WRAP, 1f).apply { leftMargin = dp(12) })
        col.addView(c, Ui.lp(this, MATCH, WRAP, top = 8))
    }
}

/** 설명서용 간단한 그림 */
class HelpPic(c: Context, private val kind: Int) : View(c) {
    companion object { const val REMOTE = 0; const val FISH = 1; const val TIDE = 2; const val MAP = 3; const val PHOTO = 4; const val GROUP = 5; const val CAL = 6; const val UPDATE = 7; const val EGI = 8 }

    private val fill = Paint(Paint.ANTI_ALIAS_FLAG)
    private val line = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.STROKE; strokeCap = Paint.Cap.ROUND; strokeJoin = Paint.Join.ROUND }

    override fun onDraw(cv: Canvas) {
        val w = width.toFloat(); val h = height.toFloat(); val u = w / 64f
        fill.color = Color.parseColor("#1C3A4F")
        cv.drawRoundRect(RectF(0f, 0f, w, h), 16 * u, 16 * u, fill)
        line.strokeWidth = 3 * u
        when (kind) {
            REMOTE -> {
                fill.color = Color.parseColor("#2E4F66"); cv.drawRoundRect(RectF(20 * u, 8 * u, 44 * u, 56 * u), 10 * u, 10 * u, fill)
                fill.color = Ui.ORANGE; cv.drawCircle(32 * u, 22 * u, 7 * u, fill)
                fill.color = Ui.BLUE; cv.drawCircle(32 * u, 40 * u, 7 * u, fill)
            }
            FISH, EGI -> {
                fill.color = if (kind == EGI) Ui.ORANGE else Ui.BLUE
                val p = Path().apply {
                    moveTo(10 * u, 32 * u); quadTo(28 * u, 14 * u, 46 * u, 32 * u); quadTo(28 * u, 50 * u, 10 * u, 32 * u); close()
                    moveTo(44 * u, 32 * u); lineTo(56 * u, 22 * u); lineTo(56 * u, 42 * u); close()
                }
                cv.drawPath(p, fill)
                if (kind == EGI) { // 에기 줄무늬 + 바늘
                    line.color = Color.parseColor("#7A3A10")
                    for (x in listOf(20, 28, 36)) cv.drawLine(x * u, 26 * u, x * u, 38 * u, line)
                    line.color = Color.WHITE; line.strokeWidth = 2 * u
                    cv.drawLine(10 * u, 32 * u, 5 * u, 28 * u, line); cv.drawLine(10 * u, 32 * u, 5 * u, 36 * u, line)
                } else {
                    fill.color = Ui.BG; cv.drawCircle(19 * u, 30 * u, 2.5f * u, fill)
                }
            }
            TIDE -> {
                line.color = Ui.BLUE
                val p = Path().apply { moveTo(6 * u, 36 * u); cubicTo(18 * u, 10 * u, 26 * u, 10 * u, 32 * u, 32 * u); cubicTo(38 * u, 54 * u, 46 * u, 54 * u, 58 * u, 28 * u) }
                cv.drawPath(p, line)
                line.color = Ui.GREEN; line.strokeWidth = 2 * u
                cv.drawLine(40 * u, 10 * u, 40 * u, 54 * u, line)
            }
            MAP -> {
                line.color = Ui.SUB; line.strokeWidth = 2.5f * u
                val p = Path().apply { moveTo(10 * u, 52 * u); quadTo(18 * u, 24 * u, 32 * u, 34 * u); quadTo(46 * u, 44 * u, 54 * u, 12 * u) }
                cv.drawPath(p, line)
                fill.color = Ui.GREEN; cv.drawCircle(10 * u, 52 * u, 4 * u, fill)
                fill.color = Ui.ORANGE; cv.drawCircle(30 * u, 33 * u, 6 * u, fill)
                fill.color = Ui.BLUE; cv.drawCircle(48 * u, 30 * u, 5 * u, fill)
            }
            PHOTO -> {
                fill.color = Color.parseColor("#2E4F66"); cv.drawRoundRect(RectF(10 * u, 18 * u, 54 * u, 50 * u), 6 * u, 6 * u, fill)
                fill.color = Color.parseColor("#2E4F66"); cv.drawRect(24 * u, 12 * u, 40 * u, 20 * u, fill)
                fill.color = Ui.BLUE; cv.drawCircle(32 * u, 34 * u, 9 * u, fill)
                fill.color = Ui.BG; cv.drawCircle(32 * u, 34 * u, 4 * u, fill)
            }
            GROUP -> {
                fill.color = Ui.ORANGE; cv.drawCircle(22 * u, 24 * u, 7 * u, fill); cv.drawRoundRect(RectF(11 * u, 34 * u, 33 * u, 52 * u), 8 * u, 8 * u, fill)
                fill.color = Ui.BLUE; cv.drawCircle(42 * u, 24 * u, 7 * u, fill); cv.drawRoundRect(RectF(31 * u, 34 * u, 53 * u, 52 * u), 8 * u, 8 * u, fill)
            }
            CAL -> {
                fill.color = Color.parseColor("#2E4F66"); cv.drawRoundRect(RectF(10 * u, 14 * u, 54 * u, 52 * u), 6 * u, 6 * u, fill)
                fill.color = Ui.ORANGE; cv.drawRect(10 * u, 14 * u, 54 * u, 22 * u, fill)
                fill.color = Ui.SUB
                for (r in 0..2) for (k in 0..3) cv.drawCircle((17 + k * 10) * u, (30 + r * 8) * u, 2 * u, fill)
                fill.color = Ui.GREEN; cv.drawCircle(37 * u, 38 * u, 4 * u, fill)
            }
            UPDATE -> {
                line.color = Ui.GREEN
                cv.drawArc(RectF(14 * u, 14 * u, 50 * u, 50 * u), 30f, 300f, false, line)
                fill.color = Ui.GREEN
                val p = Path().apply { moveTo(46 * u, 12 * u); lineTo(52 * u, 26 * u); lineTo(38 * u, 24 * u); close() }
                cv.drawPath(p, fill)
            }
        }
    }
}
